#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct QqExtensionOptions {
    #[serde(default = "empty_qq_extension_param")]
    param: Value,
    #[serde(default)]
    preserve_booleans: bool,
    #[serde(default)]
    allow_error_codes: Vec<i64>,
}

#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct QqExtensionBatchCall {
    module: String,
    method: String,
    #[serde(default = "empty_qq_extension_param")]
    param: Value,
    #[serde(default)]
    preserve_booleans: bool,
    #[serde(default)]
    allow_error_codes: Vec<i64>,
}

struct PreparedQqExtensionCall {
    request: QqApiRequest,
    allow_error_codes: BTreeSet<i64>,
}

#[derive(Clone, Copy)]
struct QqExtensionProtocol {
    web: bool,
    signed: bool,
}

fn empty_qq_extension_param() -> Value {
    Value::Object(serde_json::Map::new())
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
struct QqAudioFileSpec {
    name: &'static str,
    prefix: &'static str,
    extension: &'static str,
    encrypted: bool,
    codec: &'static str,
    bitrate: Option<u64>,
    quality: Option<Quality>,
}

const fn qq_file_spec(
    name: &'static str,
    prefix: &'static str,
    extension: &'static str,
    encrypted: bool,
    codec: &'static str,
    bitrate: Option<u64>,
    quality: Option<Quality>,
) -> QqAudioFileSpec {
    QqAudioFileSpec {
        name,
        prefix,
        extension,
        encrypted,
        codec,
        bitrate,
        quality,
    }
}

