#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum QqNewAlbumArea {
    MainlandChina,
    HongKongTaiwan,
    Western,
    Korea,
    Japan,
    Other,
}

impl QqNewAlbumArea {
    const fn id(self) -> u8 {
        match self {
            Self::MainlandChina => 1,
            Self::HongKongTaiwan => 2,
            Self::Western => 3,
            Self::Korea => 4,
            Self::Japan => 5,
            Self::Other => 6,
        }
    }

    const fn key(self) -> &'static str {
        match self {
            Self::MainlandChina => "mainland_china",
            Self::HongKongTaiwan => "hong_kong_taiwan",
            Self::Western => "western",
            Self::Korea => "korea",
            Self::Japan => "japan",
            Self::Other => "other",
        }
    }
}

