    async fn videos(
        &self,
        ids: &[String],
        request: &VideoDetailRequest,
    ) -> Result<Vec<VideoDetail>> {
        if request.kind != VideoResourceKind::Mv {
            return Err(TuneWeaveError::invalid_request(
                "QQ video details currently accept MV resources only",
            )
            .with_platform(Platform::Qq)
            .with_details(json!({ "allowed": ["mv"] })));
        }
        if ids.is_empty() || ids.len() > MAX_MV_DETAIL_ITEMS {
            return Err(TuneWeaveError::invalid_request(format!(
                "QQ MV detail batch must contain between 1 and {MAX_MV_DETAIL_ITEMS} VIDs"
            ))
            .with_platform(Platform::Qq));
        }
        self.validate_public_account(request.account.as_deref())?;
        let vids = ids
            .iter()
            .map(|vid| {
                let vid = vid.trim();
                validate_qq_media_id(vid, "MV VID")?;
                Ok(vid.to_owned())
            })
            .collect::<Result<Vec<_>>>()?;
        let response = self
            .client
            .request_android(&[qq_mv_details_request(&vids)])
            .await?
            .into_iter()
            .next()
            .ok_or_else(|| qq_data_error("QQ MV detail request returned no response"))?;
        map_qq_mv_detail_response(&vids, response)
    }

    async fn video_streams(
        &self,
        ids: &[String],
        request: &VideoStreamRequest,
    ) -> Result<Vec<VideoStream>> {
        if request.kind != VideoResourceKind::Mv {
            return Err(TuneWeaveError::invalid_request(
                "QQ video streaming currently accepts MV resources only",
            )
            .with_platform(Platform::Qq)
            .with_details(json!({ "allowed": ["mv"] })));
        }
        if !(1..=4_320).contains(&request.resolution) {
            return Err(TuneWeaveError::invalid_request(
                "QQ MV resolution must be between 1 and 4320",
            )
            .with_platform(Platform::Qq));
        }
        if ids.is_empty() || ids.len() > MAX_MV_URL_ITEMS {
            return Err(TuneWeaveError::invalid_request(format!(
                "QQ MV URL batch must contain between 1 and {MAX_MV_URL_ITEMS} VIDs"
            ))
            .with_platform(Platform::Qq));
        }
        self.validate_public_account(request.account.as_deref())?;
        let vids = ids
            .iter()
            .map(|vid| {
                let vid = vid.trim();
                validate_qq_media_id(vid, "MV VID")?;
                Ok(vid.to_owned())
            })
            .collect::<Result<Vec<_>>>()?;
        let (api_request, guid) = qq_mv_urls_request(&vids);
        let response = self
            .client
            .request_android(&[api_request])
            .await?
            .into_iter()
            .next()
            .ok_or_else(|| qq_data_error("QQ MV URL request returned no response"))?;
        map_qq_mv_url_response(&vids, request, &guid, response)
    }

    async fn account_playlists(
        &self,
        request: &tuneweave_core::PageRequest,
    ) -> Result<Page<Playlist>> {
        let account = request.account.as_deref().unwrap_or("default");
        let credential = self
            .qq_credential(Some(account))?
            .ok_or_else(|| qq_authentication_required(account, "QQ account was not found"))?;
        let encrypted_uin = qq_encrypted_uin(&credential)?;
        let limit = request.limit.clamp(1, 100);
        let created_response = self
            .client
            .request_android_with_credential(
                &[qq_created_playlists_request(credential.string_music_id())],
                Some(&credential),
            )
            .await?
            .into_iter()
            .next()
            .ok_or_else(|| qq_data_error("QQ created playlist request returned no response"))?;
        let created = parse_created_playlists(created_response.data.clone())?;
        validate_created_playlists(&created)?;
        let created_count = u32::try_from(created.playlists.len()).map_err(|_| {
            qq_data_error("QQ created playlist count exceeds the supported pagination range")
        })?;
        let created_start = request.offset.min(created_count);
        let created_available = created_count.saturating_sub(created_start);
        let created_take = limit.min(created_available);
        let remaining = limit.saturating_sub(created_take);
        let favorite_offset = request.offset.saturating_sub(created_count);
        let favorite_size = remaining.max(1);
        let favorite_response = self
            .client
            .request_android_with_credential(
                &[qq_favorite_playlists_request(
                    encrypted_uin,
                    favorite_offset,
                    favorite_size,
                )],
                Some(&credential),
            )
            .await?
            .into_iter()
            .next()
            .ok_or_else(|| qq_data_error("QQ favorite playlist request returned no response"))?;
        let favorite = parse_favorite_playlists(favorite_response.data.clone())?;
        validate_favorite_playlists(&favorite, favorite_offset, favorite_size)?;

        map_account_playlist_page(QqAccountPlaylistPageInput {
            offset: request.offset,
            limit,
            created_start,
            created_take,
            created,
            favorite,
            favorite_take: remaining,
            created_raw: created_response.raw,
            favorite_raw: favorite_response.raw,
        })
    }

