    async fn prepare_audio_file_items(
        &self,
        request: &AudioFileRequest,
    ) -> Result<Vec<PreparedQqAudioFile>> {
        if request.items.is_empty() {
            return Err(TuneWeaveError::invalid_request(
                "audio file request must contain at least one item",
            )
            .with_platform(Platform::Qq));
        }
        if request.items.len() > MAX_SONG_URL_ITEMS {
            return Err(TuneWeaveError::invalid_request(format!(
                "QQ audio file request cannot exceed {MAX_SONG_URL_ITEMS} items"
            ))
            .with_platform(Platform::Qq));
        }
        let default_spec = parse_qq_audio_file_spec(request.default_spec.as_deref())?;
        let numeric_ids = request
            .items
            .iter()
            .filter(|item| {
                item.track_ref
                    .id()
                    .chars()
                    .all(|character| character.is_ascii_digit())
            })
            .map(|item| item.track_ref.id().to_owned())
            .collect::<Vec<_>>();
        let resolved_numeric = if numeric_ids.is_empty() {
            Vec::new()
        } else {
            self.tracks(&numeric_ids, None).await?
        };
        let mut resolved_numeric = resolved_numeric.into_iter();
        request
            .items
            .iter()
            .map(|item| {
                if item.track_ref.platform() != Platform::Qq {
                    return Err(TuneWeaveError::invalid_request(
                        "QQ audio file request contains a non-QQ track reference",
                    )
                    .with_platform(Platform::Qq));
                }
                let mid = if item
                    .track_ref
                    .id()
                    .chars()
                    .all(|character| character.is_ascii_digit())
                {
                    resolved_numeric
                        .next()
                        .and_then(|track| {
                            track
                                .extensions
                                .get("mid")
                                .and_then(Value::as_str)
                                .map(str::to_owned)
                        })
                        .ok_or_else(|| qq_data_error("QQ track lookup did not return a MID"))?
                } else {
                    item.track_ref.id().to_owned()
                };
                validate_qq_media_id(&mid, "song MID")?;
                let media_id = item
                    .media_id
                    .as_deref()
                    .map(str::trim)
                    .filter(|value| !value.is_empty())
                    .map(|value| {
                        validate_qq_media_id(value, "media MID")?;
                        Ok(value.to_owned())
                    })
                    .transpose()?;
                let spec = item
                    .spec
                    .as_deref()
                    .map(|spec| parse_qq_audio_file_spec(Some(spec)))
                    .transpose()?
                    .unwrap_or(default_spec);
                let filename = match media_id.as_deref() {
                    Some(media_id) => {
                        format!("{}{media_id}{}", spec.prefix, spec.extension)
                    }
                    None => format!("{}{mid}{mid}{}", spec.prefix, spec.extension),
                };
                Ok(PreparedQqAudioFile {
                    track_ref: item.track_ref.clone(),
                    mid,
                    media_id,
                    song_type: item.song_type.unwrap_or(0),
                    spec,
                    filename,
                })
            })
            .collect()
    }

    async fn resolve_audio(
        &self,
        track: &Track,
        request: &StreamRequest,
        include_trial: bool,
    ) -> Result<QqAudioResolution> {
        validate_qq_stream_track(track)?;
        let metadata = qq_track_audio_metadata(track)?;
        let candidates = qq_playable_candidates_from_metadata(&metadata, request, include_trial)?;
        if candidates.is_empty() {
            let _ = self.qq_credential(request.account.as_deref())?;
            return Ok(QqAudioResolution {
                candidates,
                files: AudioFileBatch {
                    expires_in_seconds: 0,
                    files: Vec::new(),
                    extensions: Extensions::from([(
                        "selection".to_owned(),
                        json!("no_matching_file_metadata"),
                    )]),
                },
                dispatch: None,
                selected_index: None,
                url: None,
                backup_urls: Vec::new(),
            });
        }
        let files = self
            .audio_files(&AudioFileRequest {
                items: candidates
                    .iter()
                    .map(|candidate| AudioFileRequestItem {
                        track_ref: track.resource_ref.clone(),
                        spec: Some(candidate.spec.name.to_owned()),
                        song_type: metadata.song_type,
                        media_id: candidate.media_id.clone(),
                    })
                    .collect(),
                default_spec: Some(candidates[0].spec.name.to_owned()),
                account: request.account.clone(),
            })
            .await?;
        if files.files.len() != candidates.len() {
            return Err(qq_data_error(
                "QQ audio authorization did not preserve candidate cardinality",
            ));
        }
        let selected_index = files.files.iter().position(|file| file.available);
        let Some(selected_index) = selected_index else {
            return Ok(QqAudioResolution {
                candidates,
                files,
                dispatch: None,
                selected_index: None,
                url: None,
                backup_urls: Vec::new(),
            });
        };
        let relative_url = files.files[selected_index]
            .relative_url
            .as_deref()
            .ok_or_else(|| qq_data_error("QQ available audio file is missing its relative URL"))?;
        let dispatch = self.audio_cdn_dispatch(None).await?;
        let (url, backup_urls) = qq_cdn_media_urls(&dispatch.roots, relative_url)?;
        Ok(QqAudioResolution {
            candidates,
            files,
            dispatch: Some(dispatch),
            selected_index: Some(selected_index),
            url: Some(url),
            backup_urls,
        })
    }

