fn map_qq_vip_info(
    credential: &QqCredential,
    response: QqApiResponse,
) -> Result<MembershipSummary> {
    let vip = serde_json::from_value::<QqVipInfoResponse>(response.data)
        .map_err(|_| qq_data_error("QQ VIP information response is malformed"))?;
    let level = u32::try_from(vip.identity.level)
        .map_err(|_| qq_data_error("QQ VIP level exceeds the supported membership range"))?;
    let active = [
        vip.svip,
        vip.star,
        vip.yearly_star,
        vip.identity.vip,
        vip.identity.huge_vip,
        vip.identity.year_flag,
        vip.identity.huge_year_flag,
        vip.identity.twelve,
        vip.identity.child_vip,
        vip.identity.experience_vip,
        vip.identity.group_vip,
        vip.identity.couple_vip,
        vip.identity.ad_vip,
        vip.identity.eight,
    ]
    .into_iter()
    .any(|flag| flag > 0);
    let expires_at = (vip.userinfo.expire > 0)
        .then_some(vip.userinfo.expire)
        .map(|timestamp| {
            if timestamp > 10_000_000_000 {
                timestamp / 1_000
            } else {
                timestamp
            }
        })
        .and_then(qq_unix_rfc3339);
    let icon_url =
        (!vip.identity.icon.trim().is_empty()).then(|| vip.identity.icon.trim().to_owned());
    let user_ref = qq_ref(credential.string_music_id(), "VIP user")?;
    let vip_data = serde_json::to_value(&vip)
        .map_err(|_| qq_data_error("failed to preserve typed QQ VIP information"))?;

    Ok(MembershipSummary {
        user_ref: Some(user_ref),
        level: Some(level),
        active: Some(active),
        annual_count: None,
        expires_at,
        icon_url,
        extensions: Extensions::from([
            ("backend".to_owned(), json!("vip_login_base")),
            ("vip".to_owned(), vip_data),
            ("response".to_owned(), response.raw),
        ]),
    })
}

fn map_qq_singer_catalog(
    request: &ArtistCatalogRequest,
    selection: QqSingerCatalogSelection,
    response: QqApiResponse,
) -> Result<ArtistCatalog> {
    let data =
        serde_json::from_value::<QqSingerCatalogResponse>(response.data).map_err(|error| {
            qq_data_error(format!("QQ singer catalog response is malformed: {error}"))
        })?;
    if data.code != 0 {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            format!("QQ singer catalog failed with code {}", data.code),
        )
        .with_platform(Platform::Qq)
        .with_details(json!({ "platform_code": data.code })));
    }
    if (data.area, data.sex, data.genre) != (selection.area, selection.sex, selection.genre) {
        return Err(qq_data_error(
            "QQ singer catalog response returned different filters than requested",
        ));
    }
    let response_data = serde_json::to_value(&data)
        .map_err(|_| qq_data_error("failed to preserve typed QQ singer catalog response"))?;
    let featured_artists = data
        .hotlist
        .into_iter()
        .map(|artist| map_qq_singer_catalog_item(artist, "featured singer"))
        .collect::<Result<Vec<_>>>()?;
    let artists = data
        .singerlist
        .into_iter()
        .map(|artist| map_qq_singer_catalog_item(artist, "catalog singer"))
        .collect::<Result<Vec<_>>>()?;
    let filters = map_qq_singer_catalog_tags(data.tags)?;
    Ok(ArtistCatalog {
        platform: Platform::Qq,
        area: request.area,
        category: request.category,
        genre: request.genre,
        featured_artists,
        artists,
        filters,
        extensions: Extensions::from([
            ("area_id".to_owned(), json!(selection.area)),
            ("sex_id".to_owned(), json!(selection.sex)),
            ("genre_id".to_owned(), json!(selection.genre)),
            ("report".to_owned(), json!(data.report)),
            ("data".to_owned(), response_data),
            ("response".to_owned(), response.raw),
        ]),
    })
}

fn map_qq_singer_index(
    request: &tuneweave_core::ArtistListRequest,
    selection: QqSingerCatalogSelection,
    index: i64,
    responses: Vec<QqApiResponse>,
) -> Result<Page<Artist>> {
    let expected_windows = request.limit.div_ceil(SINGER_INDEX_PAGE_SIZE);
    if responses.len() != usize::try_from(expected_windows).unwrap_or(2) {
        return Err(qq_data_error(
            "QQ singer index request returned an inconsistent response batch",
        ));
    }
    let mut total = None;
    let mut physical_artists = Vec::new();
    let mut data_values = Vec::with_capacity(responses.len());
    let mut raw_responses = Vec::with_capacity(responses.len());
    let mut featured_artists = Vec::new();
    let mut filters = None;
    for (window, response) in responses.into_iter().enumerate() {
        let data =
            serde_json::from_value::<QqSingerIndexResponse>(response.data).map_err(|error| {
                qq_data_error(format!("QQ singer index response is malformed: {error}"))
            })?;
        if data.code != 0 {
            return Err(TuneWeaveError::new(
                ErrorCode::UpstreamError,
                format!("QQ singer index failed with code {}", data.code),
            )
            .with_platform(Platform::Qq)
            .with_details(json!({ "platform_code": data.code })));
        }
        if (data.area, data.sex, data.genre, data.index)
            != (selection.area, selection.sex, selection.genre, index)
        {
            return Err(qq_data_error(
                "QQ singer index response returned different filters than requested",
            ));
        }
        if total.is_some_and(|total| total != data.total) {
            return Err(qq_data_error(
                "QQ singer index windows returned different totals",
            ));
        }
        total = Some(data.total);
        let upstream_returned = u32::try_from(data.singerlist.len())
            .map_err(|_| qq_data_error("QQ singer index window is too large"))?;
        if upstream_returned > SINGER_INDEX_PAGE_SIZE {
            return Err(qq_data_error(
                "QQ singer index response exceeded its fixed window size",
            ));
        }
        let window = u32::try_from(window)
            .map_err(|_| qq_data_error("QQ singer index window count is too large"))?;
        let window_start = request
            .offset
            .checked_add(window.saturating_mul(SINGER_INDEX_PAGE_SIZE))
            .ok_or_else(|| qq_data_error("QQ singer index window exceeded the offset range"))?;
        let expected_returned = data
            .total
            .saturating_sub(u64::from(window_start))
            .min(u64::from(SINGER_INDEX_PAGE_SIZE));
        if u64::from(upstream_returned) != expected_returned {
            return Err(qq_data_error(
                "QQ singer index response returned an incomplete fixed window",
            ));
        }
        let data_value = serde_json::to_value(&data)
            .map_err(|_| qq_data_error("failed to preserve typed QQ singer index response"))?;
        if window == 0 {
            featured_artists = data
                .hotlist
                .into_iter()
                .map(|artist| map_qq_singer_catalog_item(artist, "featured singer"))
                .collect::<Result<Vec<_>>>()?;
            filters = Some(map_qq_singer_catalog_tags(data.tags)?);
        }
        physical_artists.extend(
            data.singerlist
                .into_iter()
                .map(|artist| map_qq_singer_catalog_item(artist, "indexed singer"))
                .collect::<Result<Vec<_>>>()?,
        );
        data_values.push(data_value);
        raw_responses.push(response.raw);
    }
    let total = total.ok_or_else(|| qq_data_error("QQ singer index returned no response"))?;
    let available = total.saturating_sub(u64::from(request.offset));
    let returned = usize::try_from(available.min(u64::from(request.limit)))
        .map_err(|_| qq_data_error("QQ singer index page exceeds this platform's capacity"))?;
    if physical_artists.len() < returned {
        return Err(qq_data_error(
            "QQ singer index response ended before the requested logical page",
        ));
    }
    let upstream_returned = physical_artists.len();
    let items = physical_artists
        .into_iter()
        .take(returned)
        .collect::<Vec<_>>();
    let limit_applied = upstream_returned > items.len();
    let returned = u32::try_from(items.len())
        .map_err(|_| qq_data_error("QQ singer index logical page is too large"))?;
    let next_offset = request.offset.checked_add(returned).ok_or_else(|| {
        qq_data_error("QQ singer index pagination exceeded the supported offset range")
    })?;
    let has_more = u64::from(next_offset) < total;
    let filters = filters.unwrap_or_else(|| ArtistCatalogFilters {
        areas: Vec::new(),
        categories: Vec::new(),
        genres: Vec::new(),
        initials: Vec::new(),
        extensions: Extensions::new(),
    });
    Ok(Page {
        items,
        pagination: PageMeta {
            limit: request.limit,
            offset: request.offset,
            total: Some(total),
            next_offset: has_more.then_some(next_offset),
            has_more,
            extensions: Extensions::from([
                ("area_id".to_owned(), json!(selection.area)),
                ("sex_id".to_owned(), json!(selection.sex)),
                ("genre_id".to_owned(), json!(selection.genre)),
                ("index_id".to_owned(), json!(index)),
                (
                    "fixed_window_size".to_owned(),
                    json!(SINGER_INDEX_PAGE_SIZE),
                ),
                ("request_windows".to_owned(), json!(expected_windows)),
                ("upstream_returned".to_owned(), json!(upstream_returned)),
                ("limit_applied".to_owned(), json!(limit_applied)),
                ("featured_artists".to_owned(), json!(featured_artists)),
                ("filters".to_owned(), json!(filters)),
                ("data".to_owned(), json!(data_values)),
                ("responses".to_owned(), json!(raw_responses)),
            ]),
        },
    })
}

fn map_qq_singer_catalog_tags(tags: Option<QqSingerCatalogTags>) -> Result<ArtistCatalogFilters> {
    let tags_present = tags.is_some();
    let tags = tags.unwrap_or_default();
    Ok(ArtistCatalogFilters {
        areas: map_qq_singer_catalog_options(tags.area, "area")?,
        categories: map_qq_singer_catalog_options(tags.sex, "category")?,
        genres: map_qq_singer_catalog_options(tags.genre, "genre")?,
        initials: map_qq_singer_catalog_options(tags.index, "initial")?,
        extensions: Extensions::from([
            ("tags_present".to_owned(), json!(tags_present)),
            ("tags_extra".to_owned(), json!(tags.extra)),
        ]),
    })
}

fn map_qq_singer_catalog_options(
    options: Vec<QqSingerCatalogOption>,
    kind: &str,
) -> Result<Vec<ArtistCatalogFilterOption>> {
    options
        .into_iter()
        .map(|option| {
            let raw = serde_json::to_value(&option).map_err(|_| {
                qq_data_error(format!("failed to preserve typed QQ singer {kind} option"))
            })?;
            Ok(ArtistCatalogFilterOption {
                id: option.id.to_string(),
                name: option.name.trim().to_owned(),
                extensions: Extensions::from([("option".to_owned(), raw)]),
            })
        })
        .collect()
}

fn map_qq_singer_catalog_item(item: QqSingerCatalogItem, context: &str) -> Result<Artist> {
    let mid = item.mid.trim();
    if !mid.is_empty() {
        validate_qq_media_id(mid, "singer MID")
            .map_err(|_| qq_data_error(format!("QQ {context} returned an invalid MID")))?;
    }
    let id = if !mid.is_empty() {
        mid.to_owned()
    } else if item.id > 0 {
        item.id.to_string()
    } else {
        return Err(qq_data_error(format!(
            "QQ {context} is missing both singer ID and MID"
        )));
    };
    let name = item.name.trim();
    if name.is_empty() {
        return Err(qq_data_error(format!(
            "QQ {context} is missing its display name"
        )));
    }
    let image_mid = [item.image_mid.as_str(), mid]
        .into_iter()
        .map(str::trim)
        .find(|value| !value.is_empty());
    if let Some(image_mid) = image_mid {
        validate_qq_image_id(image_mid)
            .map_err(|_| qq_data_error(format!("QQ {context} returned an invalid image MID")))?;
    }
    let image_mid = image_mid.map(str::to_owned);
    let avatar_url = first_qq_display_url(&[(item.image_url.as_str(), context)])?
        .or_else(|| image_mid.as_deref().map(|mid| qq_cover_url("T001", mid)));
    let raw = serde_json::to_value(&item)
        .map_err(|_| qq_data_error(format!("failed to preserve typed QQ {context}")))?;
    let aliases = [item.other_name.trim()]
        .into_iter()
        .filter(|alias| !alias.is_empty() && *alias != name)
        .map(str::to_owned)
        .collect();
    let mut extensions = Extensions::from([
        ("area_id".to_owned(), json!(item.area_id)),
        ("country_id".to_owned(), json!(item.country_id)),
        ("country".to_owned(), json!(item.country)),
        ("spell".to_owned(), json!(item.spell)),
        ("trend".to_owned(), json!(item.trend)),
        ("follower_count".to_owned(), json!(item.follower_count)),
        ("catalog_item".to_owned(), raw),
    ]);
    if item.id > 0 {
        extensions.insert("numeric_id".to_owned(), json!(item.id));
    }
    if let Some(image_mid) = image_mid {
        extensions.insert("image_mid".to_owned(), json!(image_mid));
    }
    Ok(Artist {
        resource_ref: qq_ref(&id, context)?,
        platform: Platform::Qq,
        id,
        name: name.to_owned(),
        aliases,
        description: String::new(),
        biography_sections: Vec::new(),
        avatar_url: avatar_url.clone(),
        cover_url: avatar_url,
        album_count: None,
        track_count: None,
        mv_count: None,
        video_count: None,
        identities: Vec::new(),
        extensions,
    })
}

fn map_qq_user_homepage(
    requested_encrypted_uin: &str,
    response: QqApiResponse,
) -> Result<UserProfile> {
    let homepage =
        serde_json::from_value::<QqUserHomepageResponse>(response.data).map_err(|error| {
            qq_data_error(format!("QQ user homepage response is malformed: {error}"))
        })?;
    if homepage.status != 0 {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            format!("QQ user homepage failed with status {}", homepage.status),
        )
        .with_platform(Platform::Qq)
        .with_details(json!({ "platform_status": homepage.status })));
    }
    let base = &homepage.info.base_info;
    let encrypted_uin =
        validate_qq_encrypted_uin(base.encrypted_uin.trim(), "homepage response encrypted UIN")
            .map_err(|_| qq_data_error("QQ user homepage returned an invalid encrypted UIN"))?;
    if encrypted_uin != requested_encrypted_uin {
        return Err(qq_data_error(
            "QQ user homepage returned a different encrypted UIN",
        ));
    }
    let name = base.name.trim();
    if name.is_empty() {
        return Err(qq_data_error(
            "QQ user homepage is missing its display name",
        ));
    }
    if base.user_type < 0 {
        return Err(qq_data_error(
            "QQ user homepage returned a negative user type",
        ));
    }
    let followed = match homepage.info.followed {
        0 => false,
        1 => true,
        _ => {
            return Err(qq_data_error(
                "QQ user homepage returned an invalid followed flag",
            ));
        }
    };
    for (field, value) in [("IsHost", base.is_host), ("IsSinger", base.is_singer)] {
        if !matches!(value, 0 | 1) {
            return Err(qq_data_error(format!(
                "QQ user homepage returned an invalid {field} flag"
            )));
        }
    }
    let avatar_url = first_qq_display_url(&[(base.avatar.as_str(), "homepage avatar")])?;
    let background_url =
        first_qq_display_url(&[(base.background_image.as_str(), "homepage background image")])?;
    let info_data = serde_json::to_value(&homepage.info)
        .map_err(|_| qq_data_error("failed to preserve typed QQ user homepage info"))?;
    let tab_data = serde_json::to_value(&homepage.tab_detail)
        .map_err(|_| qq_data_error("failed to preserve typed QQ user homepage tabs"))?;
    let prompt_data = serde_json::to_value(&homepage.prompt)
        .map_err(|_| qq_data_error("failed to preserve typed QQ user homepage prompt"))?;
    let user_extensions = Extensions::from([
        ("user_type".to_owned(), json!(base.user_type)),
        ("is_host".to_owned(), json!(base.is_host == 1)),
        ("is_singer".to_owned(), json!(base.is_singer == 1)),
        (
            "friend_count".to_owned(),
            json!(homepage.info.friends.count),
        ),
        (
            "visitor_count".to_owned(),
            json!(homepage.info.visitors.count),
        ),
        ("singer".to_owned(), json!(homepage.info.singer)),
    ]);
    Ok(UserProfile {
        user: User {
            resource_ref: qq_ref(encrypted_uin, "user")?,
            platform: Platform::Qq,
            id: encrypted_uin.to_owned(),
            name: name.to_owned(),
            avatar_url,
            signature: None,
            followed: Some(followed),
            mutual: None,
            extensions: user_extensions,
        },
        level: None,
        listened_track_count: None,
        playlist_count: None,
        playlist_subscriber_count: None,
        following_count: Some(homepage.info.following.count),
        follower_count: Some(homepage.info.fans.count),
        event_count: None,
        birthday: None,
        created_at: None,
        background_url,
        description: None,
        public_listening_history: None,
        extensions: Extensions::from([
            ("backend".to_owned(), json!(UserProfileBackend::Modern)),
            ("info".to_owned(), info_data),
            ("tab_detail".to_owned(), tab_data),
            ("prompt".to_owned(), prompt_data),
            ("response".to_owned(), response.raw),
        ]),
    })
}

fn map_qq_singer_homepage(requested_mid: &str, response: QqApiResponse) -> Result<Artist> {
    let homepage =
        serde_json::from_value::<QqSingerHomepageResponse>(response.data).map_err(|error| {
            qq_data_error(format!("QQ singer homepage response is malformed: {error}"))
        })?;
    if homepage.status != 0 {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            format!("QQ singer homepage failed with status {}", homepage.status),
        )
        .with_platform(Platform::Qq)
        .with_details(json!({ "platform_status": homepage.status })));
    }

    let singer = &homepage.info.singer;
    let base_info = &homepage.info.base_info;
    let singer_mid = singer.mid.trim();
    validate_qq_media_id(singer_mid, "singer MID")
        .map_err(|_| qq_data_error("QQ singer homepage returned an invalid singer MID"))?;
    if singer_mid != requested_mid {
        return Err(qq_data_error(
            "QQ singer homepage returned a different singer MID",
        ));
    }
    let name = [singer.name.as_str(), base_info.name.as_str()]
        .into_iter()
        .map(str::trim)
        .find(|value| !value.is_empty())
        .ok_or_else(|| qq_data_error("QQ singer homepage is missing its display name"))?
        .to_owned();

    let mut aliases = Vec::new();
    for alias in [singer.foreign_name.as_str(), base_info.name.as_str()] {
        let alias = alias.trim();
        if !alias.is_empty() && alias != name && !aliases.iter().any(|known| known == alias) {
            aliases.push(alias.to_owned());
        }
    }

    let (header_url, header_3d_url, header_image_mid) = match &singer.header_picture {
        QqHomepageHeaderPicture::Url(url) => (url.as_str(), "", ""),
        QqHomepageHeaderPicture::Detail(image) => (
            image.high_resolution_url.as_str(),
            image.image_3d_url.as_str(),
            image.image_mid.as_str(),
        ),
    };
    let image_mid = [singer.singer_pmid.as_str(), header_image_mid, singer_mid]
        .into_iter()
        .map(str::trim)
        .find(|value| !value.is_empty())
        .expect("validated singer MID always provides an image fallback");
    validate_qq_image_id(image_mid)
        .map_err(|_| qq_data_error("QQ singer homepage returned an invalid image MID"))?;
    let avatar_url = first_qq_display_url(&[
        (singer.singer_pic.as_str(), "singer picture"),
        (base_info.avatar.as_str(), "homepage avatar"),
    ])?
    .or_else(|| Some(qq_cover_url("T001", image_mid)));
    let cover_url = first_qq_display_url(&[
        (header_url, "singer header picture"),
        (header_3d_url, "singer 3D header picture"),
        (
            base_info.background_image.as_str(),
            "homepage background image",
        ),
    ])?
    .or_else(|| avatar_url.clone());
    let followed = match homepage.info.followed {
        0 => false,
        1 => true,
        _ => {
            return Err(qq_data_error(
                "QQ singer homepage returned an invalid followed flag",
            ));
        }
    };

    let info_data = serde_json::to_value(&homepage.info)
        .map_err(|_| qq_data_error("failed to preserve typed QQ singer homepage info"))?;
    let tab_data = serde_json::to_value(&homepage.tab_detail)
        .map_err(|_| qq_data_error("failed to preserve typed QQ singer homepage tabs"))?;
    let prompt_data = serde_json::to_value(&homepage.prompt)
        .map_err(|_| qq_data_error("failed to preserve typed QQ singer homepage prompt"))?;
    let mut extensions = Extensions::from([
        ("singer_type".to_owned(), json!(singer.singer_type)),
        ("followed".to_owned(), json!(followed)),
        ("follower_count".to_owned(), json!(homepage.info.fans.count)),
        (
            "following_count".to_owned(),
            json!(homepage.info.following.count),
        ),
        (
            "friend_count".to_owned(),
            json!(homepage.info.friends.count),
        ),
        (
            "visitor_count".to_owned(),
            json!(homepage.info.visitors.count),
        ),
        ("info".to_owned(), info_data),
        ("tab_detail".to_owned(), tab_data),
        ("prompt".to_owned(), prompt_data),
        ("response".to_owned(), response.raw),
    ]);
    if singer.id > 0 {
        extensions.insert("numeric_id".to_owned(), json!(singer.id));
    }
    let encrypted_uin = base_info.encrypted_uin.trim();
    if !encrypted_uin.is_empty() {
        extensions.insert("encrypted_uin".to_owned(), json!(encrypted_uin));
    }
    if image_mid != singer_mid {
        extensions.insert("image_mid".to_owned(), json!(image_mid));
    }

    Ok(Artist {
        resource_ref: qq_ref(singer_mid, "singer")?,
        platform: Platform::Qq,
        id: singer_mid.to_owned(),
        name,
        aliases,
        description: String::new(),
        biography_sections: Vec::new(),
        avatar_url,
        cover_url,
        album_count: None,
        track_count: None,
        mv_count: None,
        video_count: None,
        identities: Vec::new(),
        extensions,
    })
}

fn map_qq_singer_descriptions(
    requested_mids: &[String],
    response: QqApiResponse,
) -> Result<Vec<Artist>> {
    let raw_singers = response
        .data
        .get("singer_list")
        .and_then(Value::as_array)
        .cloned()
        .ok_or_else(|| {
            qq_data_error("QQ singer description response is missing its singer list")
        })?;
    let data =
        serde_json::from_value::<QqSingerDescriptionResponse>(response.data).map_err(|error| {
            qq_data_error(format!(
                "QQ singer description response is malformed: {error}"
            ))
        })?;
    if data.singers.len() != requested_mids.len() {
        return Err(qq_data_error(
            "QQ singer description response did not preserve batch cardinality",
        ));
    }
    if raw_singers.len() != data.singers.len() {
        return Err(qq_data_error(
            "QQ singer description response could not preserve every raw item",
        ));
    }
    let response_extra = serde_json::to_value(&data.extra)
        .map_err(|_| qq_data_error("failed to preserve QQ singer description response fields"))?;
    let has_response_extra = !data.extra.is_empty();
    data.singers
        .into_iter()
        .zip(raw_singers)
        .zip(requested_mids)
        .enumerate()
        .map(|(index, ((description, raw_detail), requested_mid))| {
            let mut artist = map_qq_singer_description(requested_mid, description, raw_detail)?;
            artist
                .extensions
                .insert("batch_index".to_owned(), json!(index));
            if has_response_extra {
                artist
                    .extensions
                    .insert("response_extra".to_owned(), response_extra.clone());
            }
            Ok(artist)
        })
        .collect()
}

fn map_qq_singer_description(
    requested_mid: &str,
    description: QqSingerDescription,
    detail: Value,
) -> Result<Artist> {
    let basic = &description.basic;
    let singer_mid = basic.mid.trim();
    validate_qq_media_id(singer_mid, "singer MID")
        .map_err(|_| qq_data_error("QQ singer description returned an invalid singer MID"))?;
    if singer_mid != requested_mid {
        return Err(qq_data_error(
            "QQ singer description returned a different singer MID",
        ));
    }
    if basic.id <= 0 {
        return Err(qq_data_error(
            "QQ singer description is missing a positive numeric singer ID",
        ));
    }
    let name = basic.name.trim();
    if name.is_empty() {
        return Err(qq_data_error(
            "QQ singer description is missing its display name",
        ));
    }

    let image_mid = [basic.image_mid.as_str(), singer_mid]
        .into_iter()
        .map(str::trim)
        .find(|value| !value.is_empty())
        .expect("validated singer MID provides an image fallback");
    validate_qq_image_id(image_mid)
        .map_err(|_| qq_data_error("QQ singer description returned an invalid image MID"))?;
    let wiki_url = first_qq_display_url(&[(basic.wikiurl.as_str(), "singer wiki")])?;
    let extra = &description.extra_info;
    let summary = extra.desc.trim();
    let wiki = description.wiki.trim();
    let (description_text, description_source) = if !summary.is_empty() {
        (summary.to_owned(), Some("ex_info.desc"))
    } else if !wiki.is_empty() {
        (wiki.to_owned(), Some("wiki"))
    } else {
        (String::new(), None)
    };
    let biography_sections = (!wiki.is_empty() && wiki != description_text)
        .then(|| ArtistBiographySection {
            title: "百科".to_owned(),
            text: wiki.to_owned(),
        })
        .into_iter()
        .collect();

    let mut aliases = Vec::new();
    let foreign_name = extra.foreign_name.trim();
    if !foreign_name.is_empty() && foreign_name != name {
        aliases.push(foreign_name.to_owned());
    }
    let mut identities = Vec::new();
    for identity in [
        extra.identity.as_str(),
        extra.tag.as_str(),
        extra.genre.as_str(),
        extra.instrument.as_str(),
    ] {
        let identity = identity.trim();
        if !identity.is_empty() && !identities.iter().any(|known| known == identity) {
            identities.push(identity.to_owned());
        }
    }

    let mut extensions = Extensions::from([
        ("numeric_id".to_owned(), json!(basic.id)),
        ("singer_type".to_owned(), json!(basic.singer_type)),
        ("has_photo".to_owned(), json!(basic.has_photo)),
        ("blog_flag".to_owned(), json!(extra.blog_flag)),
        ("group_list".to_owned(), json!(&description.group_list)),
        ("photos".to_owned(), json!(&description.photos)),
        ("group_info".to_owned(), json!(&description.group_info)),
        ("detail".to_owned(), detail),
    ]);
    if image_mid != singer_mid {
        extensions.insert("image_mid".to_owned(), json!(image_mid));
    }
    if let Some(wiki_url) = wiki_url {
        extensions.insert("wiki_url".to_owned(), json!(wiki_url));
    }
    if let Some(source) = description_source {
        extensions.insert("description_source".to_owned(), json!(source));
    }
    for (key, value) in [
        ("area", extra.area.as_str()),
        ("tag", extra.tag.as_str()),
        ("instrument", extra.instrument.as_str()),
        ("genre", extra.genre.as_str()),
        ("birthday", extra.birthday.as_str()),
        ("enter", extra.enter.as_str()),
    ] {
        let value = value.trim();
        if !value.is_empty() {
            extensions.insert(key.to_owned(), json!(value));
        }
    }

    Ok(Artist {
        resource_ref: qq_ref(singer_mid, "singer")?,
        platform: Platform::Qq,
        id: singer_mid.to_owned(),
        name: name.to_owned(),
        aliases,
        description: description_text,
        biography_sections,
        avatar_url: Some(qq_cover_url("T001", image_mid)),
        cover_url: None,
        album_count: None,
        track_count: None,
        mv_count: None,
        video_count: None,
        identities,
        extensions,
    })
}

fn merge_qq_singer_description(homepage: &mut Artist, description: Artist) -> Result<()> {
    if homepage.resource_ref != description.resource_ref {
        return Err(qq_data_error(
            "QQ singer homepage and description identities do not match",
        ));
    }
    if homepage.name != description.name
        && !homepage
            .aliases
            .iter()
            .any(|alias| alias == &description.name)
    {
        homepage.aliases.push(description.name.clone());
    }
    for alias in &description.aliases {
        if alias != &homepage.name && !homepage.aliases.iter().any(|known| known == alias) {
            homepage.aliases.push(alias.clone());
        }
    }
    if !description.description.is_empty() {
        homepage.description.clone_from(&description.description);
    }
    homepage
        .biography_sections
        .clone_from(&description.biography_sections);
    for identity in &description.identities {
        if !homepage.identities.iter().any(|known| known == identity) {
            homepage.identities.push(identity.clone());
        }
    }
    if homepage.avatar_url.is_none() {
        homepage.avatar_url.clone_from(&description.avatar_url);
    }
    homepage.extensions.insert(
        "description_detail".to_owned(),
        serde_json::to_value(description)
            .map_err(|_| qq_data_error("failed to preserve merged QQ singer description"))?,
    );
    Ok(())
}

fn map_qq_similar_singers(
    requested_mid: &str,
    requested_limit: u32,
    response: QqApiResponse,
) -> Result<SimilarArtistList> {
    validate_qq_media_id(requested_mid, "singer MID")?;
    let raw_singers = match response.data.get("singerlist") {
        None | Some(Value::Null) => Vec::new(),
        Some(Value::Array(items)) => items.clone(),
        Some(_) => {
            return Err(qq_data_error(
                "QQ similar singer response contains a malformed singer list",
            ));
        }
    };
    let data =
        serde_json::from_value::<QqSimilarSingerResponse>(response.data).map_err(|error| {
            qq_data_error(format!("QQ similar singer response is malformed: {error}"))
        })?;
    if data.code != 0 {
        return Err(TuneWeaveError::new(
            ErrorCode::UpstreamError,
            if data.error_message.trim().is_empty() {
                format!("QQ similar singer request failed with code {}", data.code)
            } else {
                data.error_message.trim().to_owned()
            },
        )
        .with_platform(Platform::Qq)
        .with_details(json!({ "platform_code": data.code })));
    }
    if data.singerlist.len() != raw_singers.len() {
        return Err(qq_data_error(
            "QQ similar singer response could not preserve every raw item",
        ));
    }
    let mut artists = data
        .singerlist
        .into_iter()
        .zip(raw_singers)
        .enumerate()
        .map(|(index, (singer, raw))| {
            let mid = singer.mid.trim();
            validate_qq_media_id(mid, "similar singer MID")
                .map_err(|_| qq_data_error("QQ similar singer returned an invalid MID"))?;
            if singer.id <= 0 {
                return Err(qq_data_error(
                    "QQ similar singer is missing a positive numeric ID",
                ));
            }
            let name = singer.name.trim();
            if name.is_empty() {
                return Err(qq_data_error(
                    "QQ similar singer is missing its display name",
                ));
            }
            let image_mid = [singer.image_mid.as_str(), mid]
                .into_iter()
                .map(str::trim)
                .find(|value| !value.is_empty())
                .expect("validated similar singer MID provides an image fallback");
            validate_qq_image_id(image_mid)
                .map_err(|_| qq_data_error("QQ similar singer returned an invalid image MID"))?;
            let avatar_url =
                first_qq_display_url(&[(singer.image_url.as_str(), "similar singer picture")])?
                    .or_else(|| Some(qq_cover_url("T001", image_mid)));
            let mut extensions = Extensions::from([
                ("numeric_id".to_owned(), json!(singer.id)),
                ("similarity_index".to_owned(), json!(index)),
                ("similar_singer".to_owned(), raw),
            ]);
            for (key, value) in [
                ("image_mid", image_mid),
                ("trace", singer.trace.trim()),
                ("about", singer.abt.trim()),
                ("tf", singer.tf.trim()),
            ] {
                if !value.is_empty() {
                    extensions.insert(key.to_owned(), json!(value));
                }
            }
            Ok(Artist {
                resource_ref: qq_ref(mid, "similar singer")?,
                platform: Platform::Qq,
                id: mid.to_owned(),
                name: name.to_owned(),
                aliases: Vec::new(),
                description: String::new(),
                biography_sections: Vec::new(),
                avatar_url,
                cover_url: None,
                album_count: None,
                track_count: None,
                mv_count: None,
                video_count: None,
                identities: Vec::new(),
                extensions,
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let upstream_returned = artists.len();
    let logical_limit = usize::try_from(requested_limit).unwrap_or(usize::MAX);
    if artists.len() > logical_limit {
        artists.truncate(logical_limit);
    }
    let limit_applied = upstream_returned > artists.len();
    Ok(SimilarArtistList {
        artist_ref: qq_ref(requested_mid, "singer")?,
        requested_limit,
        artists,
        extensions: Extensions::from([
            ("platform_code".to_owned(), json!(data.code)),
            ("error_message".to_owned(), json!(data.error_message)),
            ("upstream_returned".to_owned(), json!(upstream_returned)),
            ("limit_applied".to_owned(), json!(limit_applied)),
            ("response".to_owned(), response.raw),
        ]),
    })
}

fn map_qq_top_catalog(
    request: &ChartCatalogRequest,
    response: QqApiResponse,
) -> Result<ChartCatalog> {
    let data = serde_json::from_value::<QqTopCatalogResponse>(response.data).map_err(|error| {
        qq_data_error(format!("QQ toplist catalog response is malformed: {error}"))
    })?;
    let location = serde_json::to_value(&data.location)
        .map_err(|_| qq_data_error("failed to preserve QQ toplist location metadata"))?;
    let groups = data
        .group
        .into_iter()
        .map(map_qq_top_group)
        .collect::<Result<Vec<_>>>()?;
    let mut extensions = Extensions::from([
        ("refresh_interval".to_owned(), json!(data.refresh_interval)),
        ("location".to_owned(), location),
        ("response".to_owned(), response.raw),
    ]);
    let about = data.abt.trim();
    if !about.is_empty() {
        extensions.insert("about".to_owned(), json!(about));
    }
    Ok(ChartCatalog {
        platform: Platform::Qq,
        view: request.view,
        groups,
        extensions,
    })
}

fn map_qq_top_detail(
    requested_top_id: u64,
    request: &ChartTrackListRequest,
    response: QqApiResponse,
) -> Result<Page<Track>> {
    let detail = serde_json::from_value::<QqTopDetailResponse>(response.data).map_err(|error| {
        qq_data_error(format!("QQ toplist detail response is malformed: {error}"))
    })?;
    if detail.data.id != requested_top_id {
        return Err(qq_data_error(
            "QQ toplist detail response returned a different toplist ID",
        ));
    }
    if detail.songs.len() > request.limit as usize {
        return Err(qq_data_error(
            "QQ toplist detail returned more tracks than requested",
        ));
    }
    let total = detail.data.total_count;
    let chart_raw = serde_json::to_value(&detail.data)
        .map_err(|_| qq_data_error("failed to preserve QQ toplist detail metadata"))?;
    let chart = map_qq_top_summary(chart_raw.clone())?;
    let song_tags = serde_json::to_value(&detail.song_tags)
        .map_err(|_| qq_data_error("failed to preserve QQ toplist song tags"))?;
    let ext_info = serde_json::to_value(&detail.ext_info)
        .map_err(|_| qq_data_error("failed to preserve QQ toplist extension information"))?;
    let index_info = serde_json::to_value(&detail.index_info)
        .map_err(|_| qq_data_error("failed to preserve QQ toplist index information"))?;
    let items = detail
        .songs
        .into_iter()
        .enumerate()
        .map(|(index, raw)| {
            let mut track = map_track(raw)?;
            let index = u32::try_from(index)
                .map_err(|_| qq_data_error("QQ toplist page index exceeded the supported range"))?;
            let rank = request
                .offset
                .checked_add(index)
                .and_then(|value| value.checked_add(1))
                .ok_or_else(|| {
                    qq_data_error("QQ toplist rank exceeded the supported offset range")
                })?;
            track
                .extensions
                .insert("chart_rank".to_owned(), json!(rank));
            let numeric_id = track
                .extensions
                .get("numeric_id")
                .and_then(json_u64)
                .unwrap_or_default();
            let matching_tags = detail
                .song_tags
                .iter()
                .filter(|tag| tag.id == numeric_id)
                .collect::<Vec<_>>();
            if !matching_tags.is_empty() {
                let matching_tags = serde_json::to_value(matching_tags).map_err(|_| {
                    qq_data_error("failed to preserve QQ toplist track tag associations")
                })?;
                track
                    .extensions
                    .insert("toplist_tags".to_owned(), matching_tags);
            }
            Ok(track)
        })
        .collect::<Result<Vec<_>>>()?;
    let consumed = u32::try_from(items.len())
        .map_err(|_| qq_data_error("QQ toplist page exceeded the supported size"))?;
    let next = request.offset.checked_add(consumed).ok_or_else(|| {
        qq_data_error("QQ toplist pagination exceeded the supported offset range")
    })?;
    if u64::from(next) > total {
        return Err(qq_data_error(
            "QQ toplist detail returned tracks beyond its reported total",
        ));
    }
    if u64::from(request.offset) < total && items.is_empty() {
        return Err(qq_data_error(
            "QQ toplist detail returned an empty page before its reported total",
        ));
    }
    let has_more = u64::from(next) < total;
    let mut extensions = Extensions::from([
        ("toplist_id".to_owned(), json!(requested_top_id)),
        ("include_tags".to_owned(), json!(request.include_tags)),
        (
            "chart".to_owned(),
            serde_json::to_value(chart)
                .map_err(|_| qq_data_error("failed to preserve mapped QQ toplist detail"))?,
        ),
        ("toplist".to_owned(), chart_raw),
        ("song_tags".to_owned(), song_tags),
        ("extension_info".to_owned(), ext_info),
        ("index_info".to_owned(), index_info),
        ("response".to_owned(), response.raw),
    ]);
    if !detail.extra.is_empty() {
        extensions.insert("detail_extra".to_owned(), json!(detail.extra));
    }
    Ok(Page {
        items,
        pagination: PageMeta {
            limit: request.limit,
            offset: request.offset,
            total: Some(total),
            next_offset: has_more.then_some(next),
            has_more,
            extensions,
        },
    })
}

fn map_qq_top_group(raw: Value) -> Result<ChartGroup> {
    let group = serde_json::from_value::<QqTopGroup>(raw.clone())
        .map_err(|error| qq_data_error(format!("QQ toplist group is malformed: {error}")))?;
    let name = group.name.trim();
    if name.is_empty() {
        return Err(qq_data_error(
            "QQ toplist group is missing its display name",
        ));
    }
    let charts = group
        .toplist
        .into_iter()
        .map(map_qq_top_summary)
        .collect::<Result<Vec<_>>>()?;
    let target_url = normalized_qq_text(&group.feature_button_scheme);
    let mut extensions = Extensions::from([
        ("group_type".to_owned(), json!(group.group_type)),
        ("group".to_owned(), raw),
    ]);
    if let Some(text) = normalized_qq_text(&group.feature_button_text) {
        extensions.insert("feature_button_text".to_owned(), json!(text));
    }
    Ok(ChartGroup {
        code: Some(group.id.to_string()),
        name: name.to_owned(),
        display_type: Some(group.group_type.to_string()),
        target_url,
        charts,
        extensions,
    })
}

fn map_qq_top_summary(raw: Value) -> Result<Chart> {
    let summary = serde_json::from_value::<QqTopSummary>(raw.clone())
        .map_err(|error| qq_data_error(format!("QQ toplist summary is malformed: {error}")))?;
    if summary.id == 0 {
        return Err(qq_data_error("QQ toplist summary is missing a positive ID"));
    }
    let name = summary.title.trim();
    if name.is_empty() {
        return Err(qq_data_error(
            "QQ toplist summary is missing its display name",
        ));
    }
    let previews = summary
        .songs
        .into_iter()
        .map(map_qq_top_preview)
        .collect::<Result<Vec<_>>>()?;
    let cover_url = first_qq_display_url(&[
        (summary.front_picture_url.as_str(), "toplist front picture"),
        (
            summary.mobile_front_picture_url.as_str(),
            "toplist mobile front picture",
        ),
        (summary.head_picture_url.as_str(), "toplist head picture"),
        (
            summary.mobile_head_picture_url.as_str(),
            "toplist mobile head picture",
        ),
        (
            summary.musichall_picture_url.as_str(),
            "toplist music hall picture",
        ),
        (summary.top_album_url.as_str(), "toplist album picture"),
        (summary.logo_url.as_str(), "toplist logo"),
    ])?;
    let target_url = [
        summary.h5_jump_url.as_str(),
        summary.special_scheme.as_str(),
        summary.ad_jump_url.as_str(),
    ]
    .into_iter()
    .find_map(normalized_qq_text);
    let update_frequency = normalized_qq_text(&summary.update_tips);
    let chart_id = summary.id.to_string();
    let resource_id = format!("chart:{}", summary.id);
    let mut extensions = Extensions::from([
        ("numeric_id".to_owned(), json!(summary.id)),
        ("chart".to_owned(), raw),
    ]);
    for (key, value) in [
        ("title_detail", summary.title_detail),
        ("title_subtitle", summary.title_subtitle),
        ("period", summary.period),
        ("update_time", summary.update_time),
    ] {
        let value = value.trim();
        if !value.is_empty() {
            extensions.insert(key.to_owned(), json!(value));
        }
    }
    Ok(Chart {
        resource_ref: Some(qq_ref(&resource_id, "toplist")?),
        platform: Platform::Qq,
        id: Some(chart_id),
        name: name.to_owned(),
        description: summary.intro.trim().to_owned(),
        cover_url,
        update_frequency,
        updated_at_ms: None,
        track_count: Some(summary.total_count),
        play_count: Some(summary.listen_count),
        subscribed: None,
        playable: None,
        target_kind: Some("chart".to_owned()),
        target_url,
        previews,
        extensions,
    })
}

fn map_qq_top_preview(raw: Value) -> Result<ChartTrackPreview> {
    let preview = serde_json::from_value::<QqTopPreview>(raw.clone())
        .map_err(|error| qq_data_error(format!("QQ toplist preview is malformed: {error}")))?;
    let rank = u32::try_from(preview.rank)
        .ok()
        .filter(|rank| *rank > 0)
        .ok_or_else(|| qq_data_error("QQ toplist preview contains an invalid rank"))?;
    let name = preview.title.trim();
    if name.is_empty() {
        return Err(qq_data_error(
            "QQ toplist preview is missing its track name",
        ));
    }
    let track_ref = (preview.song_id > 0)
        .then(|| qq_ref(&preview.song_id.to_string(), "toplist preview track"))
        .transpose()?;
    let cover_url = first_qq_display_url(&[(preview.cover.as_str(), "toplist preview cover")])?;
    let mut extensions = Extensions::from([
        ("rank_type".to_owned(), json!(preview.rank_type)),
        ("rank_value".to_owned(), json!(preview.rank_value)),
        ("numeric_id".to_owned(), json!(preview.song_id)),
        ("song_type".to_owned(), json!(preview.song_type)),
        ("mv_id".to_owned(), json!(preview.mv_id)),
        ("preview".to_owned(), raw),
    ]);
    for (key, value) in [
        ("singer_mid", preview.singer_mid),
        ("album_mid", preview.album_mid),
        ("video_id", preview.vid),
    ] {
        let value = value.trim();
        if !value.is_empty() {
            extensions.insert(key.to_owned(), json!(value));
        }
    }
    Ok(ChartTrackPreview {
        rank: Some(rank),
        previous_rank: None,
        rank_change: None,
        track_ref,
        name: name.to_owned(),
        byline: normalized_qq_text(&preview.singer_name),
        cover_url,
        extensions,
    })
}

fn normalized_qq_text(value: &str) -> Option<String> {
    let value = value.trim();
    (!value.is_empty()).then(|| value.to_owned())
}

fn first_qq_display_url(candidates: &[(&str, &str)]) -> Result<Option<String>> {
    for (value, context) in candidates {
        let value = value.trim();
        if value.is_empty() {
            continue;
        }
        let normalized = if value.starts_with("//") {
            format!("https:{value}")
        } else {
            value.to_owned()
        };
        let url = reqwest::Url::parse(&normalized)
            .map_err(|_| qq_data_error(format!("QQ {context} URL is malformed")))?;
        if !matches!(url.scheme(), "http" | "https")
            || url.host_str().is_none()
            || !url.username().is_empty()
            || url.password().is_some()
        {
            return Err(qq_data_error(format!("QQ {context} URL is unsafe")));
        }
        return Ok(Some(normalized));
    }
    Ok(None)
}

fn map_qq_singer_homepage_tab(
    singer_mid: &str,
    request: &ArtistHomepageTabRequest,
    response: QqApiResponse,
) -> Result<ArtistHomepageTab> {
    validate_qq_media_id(singer_mid, "singer MID")?;
    let data = serde_json::from_value::<QqHomepageTabDetail>(response.data).map_err(|error| {
        qq_data_error(format!(
            "QQ singer homepage tab response is malformed: {error}"
        ))
    })?;
    let expected_tab_id = qq_singer_homepage_tab_id(request.kind);
    if data.id.trim() != expected_tab_id {
        return Err(qq_data_error(
            "QQ singer homepage tab response returned a different tab ID",
        ));
    }
    let has_more = qq_homepage_boolean(data.has_more, "HasMore")?;
    let need_show = qq_homepage_boolean(data.need_show, "NeedShowTab")?;
    let next_page = has_more
        .then(|| {
            request.page.checked_add(1).ok_or_else(|| {
                qq_data_error("QQ singer homepage tab page exceeded the supported range")
            })
        })
        .transpose()?;

    let tab_data = serde_json::to_value(&data)
        .map_err(|_| qq_data_error("failed to preserve typed QQ singer homepage tab"))?;
    let tabs = data
        .tabs
        .into_iter()
        .map(|tab| {
            let id = tab.id.trim();
            if id.is_empty() || id.len() > 64 || id.chars().any(char::is_control) {
                return Err(qq_data_error(
                    "QQ singer homepage tab metadata contains an invalid ID",
                ));
            }
            let metadata = serde_json::to_value(&tab)
                .map_err(|_| qq_data_error("failed to preserve QQ singer homepage tab metadata"))?;
            Ok(ArtistHomepageTabMetadata {
                id: id.to_owned(),
                name: tab.name.trim().to_owned(),
                title: tab.title.trim().to_owned(),
                extensions: Extensions::from([("tab".to_owned(), metadata)]),
            })
        })
        .collect::<Result<Vec<_>>>()?;
    let introduction = data
        .introduction
        .items
        .into_iter()
        .map(map_qq_homepage_introduction)
        .collect::<Result<Vec<_>>>()?;
    let tracks = data
        .songs
        .items
        .into_iter()
        .map(map_track)
        .collect::<Result<Vec<_>>>()?;
    let albums = data
        .albums
        .items
        .into_iter()
        .map(|album| map_qq_singer_album(singer_mid, album))
        .collect::<Result<Vec<_>>>()?;
    let videos = data
        .videos
        .items
        .into_iter()
        .map(|video| map_qq_singer_mv(singer_mid, video))
        .collect::<Result<Vec<_>>>()?;

    Ok(ArtistHomepageTab {
        artist_ref: qq_ref(singer_mid, "singer")?,
        kind: request.kind,
        tab_id: expected_tab_id.to_owned(),
        page: request.page,
        limit: request.limit,
        has_more,
        next_page,
        need_show: Some(need_show),
        order: data.order,
        tabs,
        introduction,
        tracks,
        albums,
        videos,
        extensions: Extensions::from([
            ("tab_detail".to_owned(), tab_data),
            ("response".to_owned(), response.raw),
        ]),
    })
}

fn qq_homepage_boolean(value: i64, field: &str) -> Result<bool> {
    match value {
        0 => Ok(false),
        1 => Ok(true),
        _ => Err(qq_data_error(format!(
            "QQ singer homepage tab returned an invalid {field} flag"
        ))),
    }
}

fn map_qq_homepage_introduction(value: Value) -> Result<ArtistHomepageIntroduction> {
    let item_type = value.get("ItemType").and_then(json_i64).ok_or_else(|| {
        qq_data_error("QQ singer homepage introduction is missing a numeric ItemType")
    })?;
    let mut titles = Vec::new();
    let mut texts = Vec::new();
    collect_qq_homepage_strings(&value, &mut titles, &mut texts);
    Ok(ArtistHomepageIntroduction {
        item_type,
        titles,
        texts,
        extensions: Extensions::from([("introduction_item".to_owned(), value)]),
    })
}

fn collect_qq_homepage_strings(value: &Value, titles: &mut Vec<String>, texts: &mut Vec<String>) {
    match value {
        Value::Object(object) => {
            for (key, value) in object {
                if matches!(key.as_str(), "Title" | "Content")
                    && let Some(text) = value
                        .as_str()
                        .map(str::trim)
                        .filter(|text| !text.is_empty())
                {
                    if key == "Title" {
                        titles.push(text.to_owned());
                    } else {
                        texts.push(text.to_owned());
                    }
                }
                collect_qq_homepage_strings(value, titles, texts);
            }
        }
        Value::Array(items) => {
            for item in items {
                collect_qq_homepage_strings(item, titles, texts);
            }
        }
        _ => {}
    }
}

fn map_qq_singer_songs(
    requested_mid: &str,
    limit: u32,
    offset: u32,
    response: QqApiResponse,
) -> Result<Page<Track>> {
    let data = serde_json::from_value::<QqSingerSongResponse>(response.data)
        .map_err(|error| qq_data_error(format!("QQ singer song response is malformed: {error}")))?;
    let singer_mid = data.singer_mid.trim();
    validate_qq_media_id(singer_mid, "singer MID")
        .map_err(|_| qq_data_error("QQ singer song response contains an invalid singer MID"))?;
    if singer_mid != requested_mid {
        return Err(qq_data_error(
            "QQ singer song response returned a different singer MID",
        ));
    }
    let upstream_returned = u32::try_from(data.songs.len())
        .map_err(|_| qq_data_error("QQ singer song page is too large"))?;
    let upstream_end = offset.checked_add(upstream_returned).ok_or_else(|| {
        qq_data_error("QQ singer song pagination exceeded the supported offset range")
    })?;
    if u64::from(upstream_end) > data.total
        || (upstream_returned == 0 && u64::from(offset) < data.total)
    {
        return Err(qq_data_error(
            "QQ singer song response has inconsistent pagination",
        ));
    }
    let returned = upstream_returned.min(limit);
    let next_offset = offset.checked_add(returned).ok_or_else(|| {
        qq_data_error("QQ singer song pagination exceeded the supported offset range")
    })?;

    let response_data = serde_json::to_value(&data)
        .map_err(|_| qq_data_error("failed to preserve typed QQ singer song response"))?;
    let returned = usize::try_from(returned)
        .map_err(|_| qq_data_error("QQ singer song page exceeds this platform's capacity"))?;
    let mut items = Vec::with_capacity(returned);
    for entry in data.songs.into_iter().take(returned) {
        let entry_data = serde_json::to_value(&entry)
            .map_err(|_| qq_data_error("failed to preserve typed QQ singer song entry"))?;
        let mut track = map_track(entry.song)?;
        track
            .extensions
            .insert("singer_song_entry".to_owned(), entry_data);
        items.push(track);
    }
    let has_more = u64::from(next_offset) < data.total;
    Ok(Page {
        items,
        pagination: PageMeta {
            limit,
            offset,
            total: Some(data.total),
            next_offset: has_more.then_some(next_offset),
            has_more,
            extensions: Extensions::from([
                ("singer_mid".to_owned(), json!(singer_mid)),
                ("order".to_owned(), json!("hot")),
                ("upstream_returned".to_owned(), json!(upstream_returned)),
                ("limit_applied".to_owned(), json!(true)),
                ("data".to_owned(), response_data),
                ("response".to_owned(), response.raw),
            ]),
        },
    })
}

