fn map_qq_new_albums(
    limit: u32,
    offset: u32,
    selection: QqNewAlbumSelection,
    response: QqApiResponse,
) -> Result<Page<Album>> {
    let data = serde_json::from_value::<QqNewAlbumResponse>(response.data)
        .map_err(|error| qq_data_error(format!("QQ new album response is malformed: {error}")))?;
    let upstream_returned = u32::try_from(data.albums.len())
        .map_err(|_| qq_data_error("QQ new album page is too large"))?;
    if upstream_returned > limit {
        return Err(qq_data_error(
            "QQ new album response exceeded the requested page size",
        ));
    }
    let next_offset = offset.checked_add(upstream_returned).ok_or_else(|| {
        qq_data_error("QQ new album pagination exceeded the supported offset range")
    })?;
    if (upstream_returned > 0 && u64::from(next_offset) > data.total)
        || (upstream_returned == 0 && u64::from(offset) < data.total)
    {
        return Err(qq_data_error(
            "QQ new album response has inconsistent pagination",
        ));
    }

    let response_data = serde_json::to_value(&data)
        .map_err(|_| qq_data_error("failed to preserve typed QQ new album response"))?;
    let items = data
        .albums
        .into_iter()
        .map(map_qq_new_album)
        .collect::<Result<Vec<_>>>()?;
    let has_more = u64::from(next_offset) < data.total;
    Ok(Page {
        items,
        pagination: PageMeta {
            limit,
            offset,
            total: Some(data.total),
            next_offset: has_more.then_some(next_offset),
            has_more,
            extensions: Extensions::from([
                ("catalog".to_owned(), json!("new")),
                ("area".to_owned(), json!(selection.area.key())),
                ("area_id".to_owned(), json!(selection.area.id())),
                ("upstream_returned".to_owned(), json!(upstream_returned)),
                ("data".to_owned(), response_data),
                ("response".to_owned(), response.raw),
            ]),
        },
    })
}

fn map_qq_new_album(album: QqNewAlbumItem) -> Result<Album> {
    let album_mid = album.mid.trim();
    if !album_mid.is_empty() {
        validate_qq_media_id(album_mid, "album MID")
            .map_err(|_| qq_data_error("QQ new album response returned an invalid album MID"))?;
    }
    let id = if !album_mid.is_empty() {
        album_mid.to_owned()
    } else if album.id > 0 {
        album.id.to_string()
    } else {
        return Err(qq_data_error(
            "QQ new album response is missing both album ID and MID",
        ));
    };
    let name = album.name.trim();
    if name.is_empty() {
        return Err(qq_data_error(
            "QQ new album response contains an album without a name",
        ));
    }
    let mut aliases = Vec::new();
    for alias in [
        album.translated_name.trim(),
        album.original_name.trim(),
        album.other_name.trim(),
    ] {
        if !alias.is_empty() && alias != name && !aliases.iter().any(|value| value == alias) {
            aliases.push(alias.to_owned());
        }
    }
    let artists = album
        .singers
        .iter()
        .map(map_qq_album_singer)
        .collect::<Result<Vec<_>>>()?;
    let cover_mid = if !album_mid.is_empty() {
        Some(album_mid.to_owned())
    } else {
        let image_mid = album.photo.pic_mid.trim();
        if image_mid.is_empty() {
            None
        } else {
            validate_qq_image_id(image_mid).map_err(|_| {
                qq_data_error("QQ new album response returned an invalid cover image MID")
            })?;
            Some(image_mid.to_owned())
        }
    };
    let entry_data = serde_json::to_value(&album)
        .map_err(|_| qq_data_error("failed to preserve typed QQ new album entry"))?;
    let company_data = serde_json::to_value(&album.company)
        .map_err(|_| qq_data_error("failed to preserve typed QQ new album company"))?;
    let photo_data = serde_json::to_value(&album.photo)
        .map_err(|_| qq_data_error("failed to preserve typed QQ new album photo"))?;
    let mut extensions = Extensions::from([
        ("mid".to_owned(), json!(album.mid)),
        ("album_type".to_owned(), json!(album.album_type)),
        ("area".to_owned(), json!(album.area)),
        ("genre".to_owned(), json!(album.genre)),
        ("language".to_owned(), json!(album.language)),
        (
            "playable_track_count".to_owned(),
            json!(album.ex.playable_track_count),
        ),
        (
            "long_audio_count".to_owned(),
            json!(album.ex.long_audio_count),
        ),
        ("recommendation".to_owned(), json!(album.ex.recommendation)),
        (
            "short_recommendation".to_owned(),
            json!(album.ex.short_recommendation),
        ),
        ("company_detail".to_owned(), company_data),
        ("photo".to_owned(), photo_data),
        ("new_album_entry".to_owned(), entry_data),
    ]);
    if album.id > 0 {
        extensions.insert("numeric_id".to_owned(), json!(album.id));
    }

    Ok(Album {
        resource_ref: qq_ref(&id, "album")?,
        platform: Platform::Qq,
        id,
        name: name.to_owned(),
        aliases,
        artists,
        description: album.ex.desc.trim().to_owned(),
        cover_url: cover_mid.map(|mid| qq_cover_url("T002", &mid)),
        published_at: (!album.released_at.trim().is_empty())
            .then(|| album.released_at.trim().to_owned()),
        track_count: Some(album.ex.track_count),
        company: (!album.company.name.trim().is_empty())
            .then(|| album.company.name.trim().to_owned()),
        kind: None,
        extensions,
    })
}

fn map_qq_album_detail(requested: &QqAlbumIdentifier, response: QqApiResponse) -> Result<Album> {
    let detail = serde_json::from_value::<QqAlbumDetailResponse>(response.data)
        .map_err(|_| qq_data_error("QQ album detail response is malformed"))?;
    let album_mid = detail.album.mid.trim();
    if !album_mid.is_empty() {
        validate_qq_media_id(album_mid, "album MID")
            .map_err(|_| qq_data_error("QQ album detail returned an invalid album MID"))?;
    }
    match requested {
        QqAlbumIdentifier::Numeric(id) if detail.album.id > 0 && detail.album.id != *id => {
            return Err(qq_data_error(
                "QQ album detail returned a different numeric album ID",
            ));
        }
        QqAlbumIdentifier::Mid(mid) if !album_mid.is_empty() && album_mid != mid => {
            return Err(qq_data_error(
                "QQ album detail returned a different album MID",
            ));
        }
        _ => {}
    }
    let id = if !album_mid.is_empty() {
        album_mid.to_owned()
    } else if detail.album.id > 0 {
        detail.album.id.to_string()
    } else {
        return Err(qq_data_error(
            "QQ album detail is missing both album ID and MID",
        ));
    };
    let name = [detail.album.name.as_str(), detail.album.title.as_str()]
        .into_iter()
        .map(str::trim)
        .find(|value| !value.is_empty())
        .ok_or_else(|| qq_data_error("QQ album detail is missing its name"))?
        .to_owned();
    let aliases = [detail.album.subtitle.trim()]
        .into_iter()
        .filter(|value| !value.is_empty() && *value != name)
        .map(str::to_owned)
        .collect();
    let artists = detail
        .singer
        .singers
        .iter()
        .map(map_qq_album_singer)
        .collect::<Result<Vec<_>>>()?;
    let cover_mid = if !album_mid.is_empty() {
        Some(album_mid)
    } else {
        let pmid = detail.album.pmid.trim();
        (!pmid.is_empty()).then_some(pmid)
    };
    let cover_url = cover_mid
        .map(|mid| {
            validate_qq_media_id(mid, "album cover MID")
                .map_err(|_| qq_data_error("QQ album detail returned an invalid cover MID"))?;
            Ok(qq_cover_url("T002", mid))
        })
        .transpose()?;
    let album_data = serde_json::to_value(&detail.album)
        .map_err(|_| qq_data_error("failed to preserve typed QQ album detail"))?;
    let company_data = serde_json::to_value(&detail.company)
        .map_err(|_| qq_data_error("failed to preserve typed QQ album company"))?;
    let singer_data = serde_json::to_value(&detail.singer)
        .map_err(|_| qq_data_error("failed to preserve typed QQ album singers"))?;
    let mut extensions = Extensions::from([
        ("numeric_id".to_owned(), json!(detail.album.id)),
        ("mid".to_owned(), json!(detail.album.mid)),
        ("subtitle".to_owned(), json!(detail.album.subtitle)),
        ("language".to_owned(), json!(detail.album.language)),
        ("genre".to_owned(), json!(detail.album.genre)),
        ("wiki_url".to_owned(), json!(detail.album.wikiurl)),
        ("company".to_owned(), company_data),
        ("singer".to_owned(), singer_data),
        ("album".to_owned(), album_data),
        ("response".to_owned(), response.raw),
    ]);
    extensions.insert(
        "requested_identifier_kind".to_owned(),
        json!(match requested {
            QqAlbumIdentifier::Numeric(_) => "numeric_id",
            QqAlbumIdentifier::Mid(_) => "mid",
        }),
    );
    Ok(Album {
        resource_ref: qq_ref(&id, "album")?,
        platform: Platform::Qq,
        id,
        name,
        aliases,
        artists,
        description: detail.album.desc.trim().to_owned(),
        cover_url,
        published_at: (!detail.album.published_at.trim().is_empty())
            .then(|| detail.album.published_at.trim().to_owned()),
        track_count: None,
        company: (!detail.company.name.trim().is_empty())
            .then(|| detail.company.name.trim().to_owned()),
        kind: (!detail.album.album_type.trim().is_empty())
            .then(|| detail.album.album_type.trim().to_owned()),
        extensions,
    })
}

fn map_qq_album_singer(singer: &QqAlbumSinger) -> Result<ArtistSummary> {
    let name = [
        singer.name.as_str(),
        singer.title.as_str(),
        singer.foreign_name.as_str(),
    ]
    .into_iter()
    .map(str::trim)
    .find(|value| !value.is_empty())
    .ok_or_else(|| qq_data_error("QQ album detail contains a singer without a name"))?;
    let mid = singer.mid.trim();
    let resource_ref = if !mid.is_empty() {
        validate_qq_media_id(mid, "album singer MID")
            .map_err(|_| qq_data_error("QQ album detail returned an invalid singer MID"))?;
        Some(qq_ref(mid, "album singer")?)
    } else if singer.id > 0 {
        Some(qq_ref(&singer.id.to_string(), "album singer")?)
    } else {
        None
    };
    Ok(ArtistSummary {
        resource_ref,
        name: name.to_owned(),
    })
}

fn map_qq_album_songs(
    requested: &QqAlbumIdentifier,
    limit: u32,
    offset: u32,
    response: QqApiResponse,
) -> Result<Page<Track>> {
    let data = serde_json::from_value::<QqAlbumSongResponse>(response.data)
        .map_err(|_| qq_data_error("QQ album song response is malformed"))?;
    let album_mid = data.album_mid.trim();
    validate_qq_media_id(album_mid, "album MID")
        .map_err(|_| qq_data_error("QQ album song response contains an invalid album MID"))?;
    if let QqAlbumIdentifier::Mid(requested_mid) = requested
        && album_mid != requested_mid
    {
        return Err(qq_data_error(
            "QQ album song response returned a different album MID",
        ));
    }
    let returned = u32::try_from(data.songs.len())
        .map_err(|_| qq_data_error("QQ album song page is too large"))?;
    if returned > limit {
        return Err(qq_data_error(
            "QQ album song response exceeded the requested page size",
        ));
    }
    let next_offset = offset.checked_add(returned).ok_or_else(|| {
        qq_data_error("QQ album song pagination exceeded the supported offset range")
    })?;
    if u64::from(next_offset) > data.total || (returned == 0 && u64::from(offset) < data.total) {
        return Err(qq_data_error(
            "QQ album song response has inconsistent pagination",
        ));
    }
    let response_data = serde_json::to_value(&data)
        .map_err(|_| qq_data_error("failed to preserve typed QQ album song response"))?;
    let mut items = Vec::with_capacity(data.songs.len());
    for entry in data.songs {
        let entry_data = serde_json::to_value(&entry)
            .map_err(|_| qq_data_error("failed to preserve typed QQ album song entry"))?;
        let mut track = map_track(entry.song)?;
        if let Some(resource_ref) = track
            .album
            .as_ref()
            .and_then(|album| album.resource_ref.as_ref())
            && (resource_ref.platform() != Platform::Qq || resource_ref.id() != album_mid)
        {
            return Err(qq_data_error(
                "QQ album song response contains a track from a different album",
            ));
        }
        track
            .extensions
            .insert("album_song_entry".to_owned(), entry_data);
        items.push(track);
    }
    let has_more = u64::from(next_offset) < data.total;
    Ok(Page {
        items,
        pagination: PageMeta {
            limit,
            offset,
            total: Some(data.total),
            next_offset: has_more.then_some(next_offset),
            has_more,
            extensions: Extensions::from([
                ("album_mid".to_owned(), json!(album_mid)),
                (
                    "requested_identifier_kind".to_owned(),
                    json!(match requested {
                        QqAlbumIdentifier::Numeric(_) => "numeric_id",
                        QqAlbumIdentifier::Mid(_) => "mid",
                    }),
                ),
                ("data".to_owned(), response_data),
                ("response".to_owned(), response.raw),
            ]),
        },
    })
}

fn map_qq_mv_detail_response(
    requested: &[String],
    response: QqApiResponse,
) -> Result<Vec<VideoDetail>> {
    let QqApiResponse { data, raw } = response;
    let details = serde_json::from_value::<BTreeMap<String, QqMvDetail>>(data)
        .map_err(|error| qq_data_error(format!("QQ MV detail response is malformed: {error}")))?;
    let requested_unique = requested
        .iter()
        .map(String::as_str)
        .collect::<BTreeSet<_>>();
    for (key, detail) in &details {
        validate_qq_media_id(key, "MV VID")
            .map_err(|_| qq_data_error("QQ MV detail response contains an invalid VID key"))?;
        if !requested_unique.contains(key.as_str()) {
            return Err(qq_data_error(
                "QQ MV detail response returned an unrequested VID",
            ));
        }
        let detail_vid = detail.vid.trim();
        validate_qq_media_id(detail_vid, "MV VID")
            .map_err(|_| qq_data_error("QQ MV detail response contains an invalid detail VID"))?;
        if detail_vid != key {
            return Err(qq_data_error(
                "QQ MV detail response key and detail VID do not match",
            ));
        }
    }
    if details.len() != requested_unique.len() {
        return Err(qq_data_error(
            "QQ MV detail response did not return every requested VID",
        ));
    }
    let response_metadata = qq_response_metadata(raw);
    requested
        .iter()
        .map(|vid| {
            let detail = details.get(vid).cloned().ok_or_else(|| {
                qq_data_error(format!(
                    "QQ MV detail response is missing requested VID {vid}"
                ))
            })?;
            map_qq_mv_detail(detail, response_metadata.clone())
        })
        .collect()
}

fn map_qq_mv_detail(detail: QqMvDetail, response_metadata: Value) -> Result<VideoDetail> {
    let vid = detail.vid.trim().to_owned();
    validate_qq_media_id(&vid, "MV VID")
        .map_err(|_| qq_data_error("QQ MV detail response returned an invalid VID"))?;
    let title = [detail.name.trim(), detail.title.trim()]
        .into_iter()
        .find(|title| !title.is_empty())
        .ok_or_else(|| qq_data_error("QQ MV detail response is missing its name"))?
        .to_owned();
    let creators = detail
        .singers
        .iter()
        .map(map_qq_mv_detail_singer)
        .collect::<Result<Vec<_>>>()?;
    let duration_ms = (detail.duration > 0)
        .then(|| {
            detail
                .duration
                .checked_mul(1_000)
                .ok_or_else(|| qq_data_error("QQ MV detail duration is out of range"))
        })
        .transpose()?;
    let detail_data = serde_json::to_value(&detail)
        .map_err(|_| qq_data_error("failed to preserve typed QQ MV detail"))?;
    let subscribed = match detail.isfav {
        0 => Some(false),
        1 => Some(true),
        _ => None,
    };
    let mut video_extensions = Extensions::from([
        ("numeric_id".to_owned(), json!(detail.sid)),
        ("vid".to_owned(), json!(detail.vid)),
        ("mv_type".to_owned(), json!(detail.video_type)),
        ("video_switch".to_owned(), json!(detail.video_switch)),
        ("message".to_owned(), json!(detail.msg)),
        ("gmid".to_owned(), json!(detail.gmid)),
        ("related_song_ids".to_owned(), json!(detail.related_songs)),
        (
            "published_at_unix_seconds".to_owned(),
            json!(detail.pubdate),
        ),
        ("mv_detail".to_owned(), detail_data.clone()),
    ]);
    video_extensions.insert(
        "uploader".to_owned(),
        json!({
            "avatar_url": detail.uploader_headurl,
            "name": detail.uploader_nick,
            "encrypted_uin": detail.uploader_encuin,
            "uin": detail.uploader_uin,
            "followed": match detail.uploader_hasfollow { Some(0) => Some(false), Some(1) => Some(true), _ => None },
            "follower_count": detail.uploader_follower_num
        }),
    );
    let video = Video {
        resource_ref: qq_ref(&vid, "MV")?,
        platform: Platform::Qq,
        id: vid,
        title,
        creators,
        description: detail.desc.trim().to_owned(),
        cover_url: (!detail.cover_pic.trim().is_empty())
            .then(|| detail.cover_pic.trim().to_owned()),
        duration_ms,
        published_at: (detail.pubdate > 0).then(|| detail.pubdate.to_string()),
        play_count: Some(detail.playcnt),
        subscribed,
        extensions: video_extensions,
    };
    Ok(VideoDetail {
        kind: VideoResourceKind::Mv,
        video,
        resolutions: Vec::new(),
        extensions: Extensions::from([
            ("mv_detail".to_owned(), detail_data),
            ("response_metadata".to_owned(), response_metadata),
        ]),
    })
}

fn map_qq_mv_detail_singer(singer: &QqAlbumSinger) -> Result<CreatorSummary> {
    let name = [singer.name.as_str(), singer.title.as_str()]
        .into_iter()
        .map(str::trim)
        .find(|name| !name.is_empty())
        .ok_or_else(|| qq_data_error("QQ MV detail contains a singer without a name"))?;
    let mid = singer.mid.trim();
    let resource_ref = if !mid.is_empty() {
        validate_qq_media_id(mid, "MV singer MID")
            .map_err(|_| qq_data_error("QQ MV detail returned an invalid singer MID"))?;
        Some(qq_ref(mid, "MV singer")?)
    } else if singer.id > 0 {
        Some(qq_ref(&singer.id.to_string(), "MV singer")?)
    } else {
        None
    };
    let image_mid = if !mid.is_empty() {
        Some(mid)
    } else {
        let pmid = singer.pmid.trim();
        (!pmid.is_empty()).then_some(pmid)
    };
    let avatar_url = image_mid
        .map(|image_mid| {
            validate_qq_media_id(image_mid, "MV singer image MID")
                .map_err(|_| qq_data_error("QQ MV detail returned an invalid singer image MID"))?;
            Ok(qq_cover_url("T001", image_mid))
        })
        .transpose()?;
    Ok(CreatorSummary {
        resource_ref,
        name: name.to_owned(),
        avatar_url,
    })
}

fn qq_response_metadata(mut raw: Value) -> Value {
    if let Some(object) = raw.as_object_mut() {
        object.remove("data");
        for (key, value) in object.iter_mut() {
            if key.starts_with("req_")
                && let Some(response) = value.as_object_mut()
            {
                response.remove("data");
            }
        }
    }
    raw
}

fn map_qq_mv_url_response(
    requested: &[String],
    request: &VideoStreamRequest,
    guid: &str,
    response: QqApiResponse,
) -> Result<Vec<VideoStream>> {
    let groups = serde_json::from_value::<BTreeMap<String, QqMvUrlSet>>(response.data)
        .map_err(|_| qq_data_error("QQ MV URL response is malformed"))?;
    let mut streams = Vec::with_capacity(requested.len());
    for vid in requested {
        let group = groups.get(vid).ok_or_else(|| {
            qq_data_error(format!("QQ MV URL response is missing requested VID {vid}"))
        })?;
        streams.push(map_qq_mv_url_group(
            vid,
            request,
            guid,
            group,
            &response.raw,
        )?);
    }
    Ok(streams)
}

fn map_qq_mv_url_group(
    vid: &str,
    request: &VideoStreamRequest,
    guid: &str,
    group: &QqMvUrlSet,
    raw_response: &Value,
) -> Result<VideoStream> {
    let mut candidates = Vec::new();
    for (protocol, items) in [
        (QqMvProtocol::Mp4, group.mp4.as_slice()),
        (QqMvProtocol::Hls, group.hls.as_slice()),
    ] {
        for item in items {
            let (urls, url_source) = qq_mv_item_urls(item)?;
            if item.code == 0 && !urls.is_empty() {
                candidates.push(QqMvCandidate {
                    protocol,
                    item,
                    resolution: qq_mv_filetype_resolution(item.filetype),
                    urls,
                    url_source,
                });
            }
        }
    }
    let selected = candidates
        .iter()
        .min_by_key(|candidate| qq_mv_candidate_key(candidate, request.resolution));
    let platform_code = selected.map_or_else(
        || {
            group
                .mp4
                .iter()
                .chain(&group.hls)
                .map(|item| item.code)
                .find(|code| *code != 0)
        },
        |candidate| Some(candidate.item.code),
    );
    let group_value = serde_json::to_value(group)
        .map_err(|_| qq_data_error("failed to preserve typed QQ MV URL response"))?;
    let raw_object = raw_response
        .as_object()
        .ok_or_else(|| qq_data_error("QQ MV URL response envelope is not an object"))?;
    let mut item_response = raw_object
        .iter()
        .filter(|(key, _)| key.as_str() != "data")
        .map(|(key, value)| (key.clone(), value.clone()))
        .collect::<serde_json::Map<_, _>>();
    let mut item_data = serde_json::Map::new();
    item_data.insert(vid.to_owned(), group_value.clone());
    item_response.insert("data".to_owned(), Value::Object(item_data));
    let mut extensions = Extensions::from([
        ("request_guid".to_owned(), json!(guid)),
        ("svp_flag".to_owned(), json!(group.svp_flag)),
        ("urls".to_owned(), group_value),
        ("response".to_owned(), Value::Object(item_response)),
    ]);
    if let Some(candidate) = selected {
        extensions.insert(
            "selected_protocol".to_owned(),
            json!(candidate.protocol.name()),
        );
        extensions.insert(
            "selected_filetype".to_owned(),
            json!(candidate.item.filetype),
        );
        extensions.insert(
            "selected_new_file_type".to_owned(),
            json!(candidate.item.new_file_type),
        );
        extensions.insert(
            "selected_url_source".to_owned(),
            json!(candidate.url_source),
        );
        extensions.insert("selected_filename".to_owned(), json!(candidate.item.cn));
        extensions.insert("selected_vkey".to_owned(), json!(candidate.item.vkey));
        extensions.insert(
            "selected_format_code".to_owned(),
            json!(candidate.item.format),
        );
    }
    let url = selected.and_then(|candidate| candidate.urls.first().cloned());
    let backup_urls = selected.map_or_else(Vec::new, |candidate| {
        candidate.urls.iter().skip(1).cloned().collect()
    });
    let available = url.is_some();
    Ok(VideoStream {
        video_ref: qq_ref(vid, "MV")?,
        platform: Platform::Qq,
        available,
        url,
        backup_urls,
        headers: BTreeMap::new(),
        expires_at: selected
            .filter(|candidate| candidate.item.expire > 0)
            .and_then(|candidate| qq_expiration_rfc3339(candidate.item.expire)),
        format: selected.map(|candidate| candidate.protocol.name().to_owned()),
        codec: selected.and_then(|candidate| qq_mv_codec(candidate.item.format)),
        width: None,
        height: selected.and_then(|candidate| candidate.resolution),
        size: selected.and_then(|candidate| {
            (candidate.item.file_size > 0).then_some(candidate.item.file_size)
        }),
        duration_ms: (group.duration > 0)
            .then(|| group.duration.checked_mul(1_000))
            .flatten(),
        requested_resolution: request.resolution,
        actual_resolution: selected.and_then(|candidate| candidate.resolution),
        platform_code,
        fee: None,
        message: (!available).then(|| "QQ did not return a playable MV URL".to_owned()),
        extensions,
    })
}

fn qq_mv_item_urls(item: &QqMvUrlItem) -> Result<(Vec<String>, &'static str)> {
    let mut urls = Vec::new();
    let mut seen = BTreeSet::new();
    let mut source = None;
    for (name, values) in [
        ("url", item.url.as_slice()),
        ("comm_url", item.comm_url.as_slice()),
        ("freeflow_url", item.freeflow_url.as_slice()),
    ] {
        for value in values {
            let value = validate_qq_mv_url(value)?;
            if seen.insert(value.clone()) {
                source.get_or_insert(name);
                urls.push(value);
            }
        }
    }
    if !item.m3u8.trim().is_empty() {
        let value = validate_qq_mv_url(&item.m3u8)?;
        if seen.insert(value.clone()) {
            source.get_or_insert("m3u8");
            urls.push(value);
        }
    }
    Ok((urls, source.unwrap_or("none")))
}

fn validate_qq_mv_url(value: &str) -> Result<String> {
    let value = value.trim();
    let url = reqwest::Url::parse(value)
        .map_err(|_| qq_data_error("QQ MV service returned an invalid media URL"))?;
    let host = url
        .host_str()
        .ok_or_else(|| qq_data_error("QQ MV service returned a media URL without a host"))?;
    let trusted_host = ["qq.com", "tencentmusic.com", "gtimg.cn", "qpic.cn"]
        .into_iter()
        .any(|domain| host == domain || host.ends_with(&format!(".{domain}")));
    if !matches!(url.scheme(), "http" | "https")
        || !url.username().is_empty()
        || url.password().is_some()
        || !trusted_host
    {
        return Err(qq_data_error("QQ MV service returned an unsafe media URL"));
    }
    Ok(value.to_owned())
}

const fn qq_mv_filetype_resolution(filetype: u64) -> Option<u32> {
    match filetype {
        10 => Some(360),
        20 => Some(480),
        30 => Some(720),
        40 => Some(1080),
        50 => Some(1440),
        60 => Some(2160),
        _ => None,
    }
}

fn qq_mv_candidate_key(candidate: &QqMvCandidate<'_>, requested: u32) -> (u8, u32, u8) {
    let (class, distance) = match candidate.resolution {
        Some(resolution) if resolution <= requested => (0, u32::MAX - resolution),
        Some(resolution) => (1, resolution - requested),
        None => (2, 0),
    };
    (class, distance, candidate.protocol.preference())
}

fn qq_mv_codec(format: u64) -> Option<String> {
    match format {
        264 => Some("h264".to_owned()),
        265 => Some("h265".to_owned()),
        _ => None,
    }
}

