    #[test]
    fn singing_annotations_info_request_and_mapping_preserve_boolean_semantics() {
        let request = singing_annotations_info_request(97_773);
        assert_eq!(request.module, LYRIC_MODULE);
        assert_eq!(request.method, "GetSingingAnnotationsInfo");
        assert_eq!(
            request.param,
            json!({
                "songID": 97_773,
                "needNum": false
            })
        );

        for (value, expected) in [
            (json!(true), true),
            (json!(1), true),
            (json!("true"), true),
            (json!(false), false),
            (json!(0), false),
            (json!("0"), false),
        ] {
            let mapped = map_singing_annotations_info(
                QqTrackIdentifier::Numeric(97_773),
                97_773,
                response(json!({
                    "hasSingingAnnotationsLyric": value,
                    "annotationCount": 3
                })),
            )
            .expect("map singing annotations availability");
            assert_eq!(mapped.track_ref.to_string(), "qq:97773");
            assert_eq!(mapped.available, expected);
            assert_eq!(mapped.extensions["numeric_id"], 97_773);
            assert_eq!(mapped.extensions["data"]["annotationCount"], 3);
            assert_eq!(mapped.extensions["response"]["code"], 0);
        }

        let missing = map_singing_annotations_info(
            QqTrackIdentifier::Mid("0039MnYb0qxYhV".to_owned()),
            97_773,
            response(json!({"futureField": "preserved"})),
        )
        .expect("missing availability defaults to false");
        assert_eq!(missing.track_ref.to_string(), "qq:0039MnYb0qxYhV");
        assert!(!missing.available);
        assert_eq!(missing.extensions["data"]["futureField"], "preserved");

        for malformed in [json!("yes"), json!([]), json!({}), Value::Null] {
            let error = map_singing_annotations_info(
                QqTrackIdentifier::Numeric(97_773),
                97_773,
                response(json!({"hasSingingAnnotationsLyric": malformed})),
            )
            .expect_err("malformed availability flag");
            assert_eq!(error.code, ErrorCode::UpstreamError);
        }
    }

    #[tokio::test]
    async fn singing_annotations_availability_rejects_invalid_identity_and_account_before_network()
    {
        let provider = QqProvider::new(QqConfig::default()).expect("provider");
        let account_error = provider
            .singing_annotations_availability("97773", Some("missing-account"))
            .await
            .expect_err("missing named account");
        assert_eq!(account_error.code, ErrorCode::AuthenticationRequired);
        assert_eq!(account_error.details["account"], "missing-account");

        let identity_error = provider
            .singing_annotations_availability("0", None)
            .await
            .expect_err("zero numeric track ID");
        assert_eq!(identity_error.code, ErrorCode::InvalidRequest);

        let account_error = provider
            .multi_style_lyric_translations("496097762", Some("missing-account"))
            .await
            .expect_err("multi-style missing named account");
        assert_eq!(account_error.code, ErrorCode::AuthenticationRequired);

        let identity_error = provider
            .multi_style_lyric_translations("0", None)
            .await
            .expect_err("multi-style zero numeric track ID");
        assert_eq!(identity_error.code, ErrorCode::InvalidRequest);

        let account_error = provider
            .ai_lyric_dictionary_availability("7137686", Some("missing-account"))
            .await
            .expect_err("AI dictionary missing named account");
        assert_eq!(account_error.code, ErrorCode::AuthenticationRequired);

        let identity_error = provider
            .ai_lyric_dictionary_availability("0", None)
            .await
            .expect_err("AI dictionary zero numeric track ID");
        assert_eq!(identity_error.code, ErrorCode::InvalidRequest);

        let account_error = provider
            .ai_lyric_dictionary("7137686", Some("missing-account"))
            .await
            .expect_err("AI dictionary detail missing named account");
        assert_eq!(account_error.code, ErrorCode::AuthenticationRequired);

        let identity_error = provider
            .ai_lyric_dictionary("0", None)
            .await
            .expect_err("AI dictionary detail zero numeric track ID");
        assert_eq!(identity_error.code, ErrorCode::InvalidRequest);
    }

    #[test]
    fn multi_style_lyric_request_and_mapping_preserve_order_and_decrypt_each_item() {
        let request = multi_style_lyric_request(496_097_762);
        assert_eq!(request.module, LYRIC_MODULE);
        assert_eq!(request.method, "BatchGetMultiStyleTransLyric");
        assert_eq!(request.param, json!({"songID": 496_097_762_u64}));

        let encrypted =
            "32DABB4C5E9846FA00500DAD626F835FEAF8FC836D78403DAE4DC6ACD55A35D4C56A9C418E42B35F";
        let mapped = map_multi_style_lyric_response(
            QqTrackIdentifier::Mid("003exampleMid".to_owned()),
            496_097_762,
            response(json!({
                "lyrics": [
                    {
                        "style": 0,
                        "styleName": "诗意",
                        "lyric": encrypted,
                        "timestamp": 1764397510,
                        "futureItemField": "first"
                    },
                    {
                        "style": "1",
                        "styleName": "粤语",
                        "lyric": encrypted,
                        "timestamp": "1764397511"
                    }
                ],
                "futureTopField": true
            })),
        )
        .expect("map multi-style translations");
        assert_eq!(mapped.track_ref.to_string(), "qq:003exampleMid");
        assert_eq!(mapped.lyrics.len(), 2);
        assert_eq!(mapped.lyrics[0].style, 0);
        assert_eq!(mapped.lyrics[0].style_name, "诗意");
        assert_eq!(mapped.lyrics[0].lyric, "[00:01.00]TuneWeave QRC 测试\n");
        assert_eq!(mapped.lyrics[0].timestamp, 1_764_397_510);
        assert_eq!(
            mapped.lyrics[0].extensions["response"]["futureItemField"],
            "first"
        );
        assert_eq!(mapped.lyrics[1].style, 1);
        assert_eq!(mapped.lyrics[1].style_name, "粤语");
        assert_eq!(mapped.lyrics[1].timestamp, 1_764_397_511);
        assert_eq!(mapped.extensions["numeric_id"], 496_097_762_u64);
        assert_eq!(mapped.extensions["data"]["futureTopField"], true);
        assert_eq!(mapped.extensions["response"]["code"], 0);

        let empty = map_multi_style_lyric_response(
            QqTrackIdentifier::Numeric(496_097_762),
            496_097_762,
            response(json!({})),
        )
        .expect("missing list follows upstream empty default");
        assert_eq!(empty.track_ref.to_string(), "qq:496097762");
        assert!(empty.lyrics.is_empty());
    }

