    #[test]
    fn playlist_deletion_uses_directory_identity_and_preserves_missing_results() {
        let playlist_refs = vec![
            ResourceRef::new(Platform::Qq, "dir:301").expect("first directory reference"),
            ResourceRef::new(Platform::Qq, "dir:302").expect("second directory reference"),
        ];
        let targets =
            qq_playlist_delete_requests(&playlist_refs).expect("playlist deletion requests");
        assert_eq!(targets.len(), 2);
        assert_eq!(targets[0].1, 301);
        assert_eq!(targets[0].2.module, "music.musicasset.PlaylistBaseWrite");
        assert_eq!(targets[0].2.method, "DelPlaylist");
        assert_eq!(targets[0].2.param, json!({"dirId": 301}));

        let result = map_qq_playlist_deletions(
            targets,
            vec![
                QqApiResponse {
                    data: json!({
                        "retCode": 0,
                        "result": {"tid": 7001, "dirId": 301, "dirName": "通勤"}
                    }),
                    raw: json!({"code": 0, "data": {"retCode": 0}}),
                },
                QqApiResponse {
                    data: json!({
                        "retCode": 0,
                        "result": {"tid": 0, "dirId": 0, "dirName": ""}
                    }),
                    raw: json!({"code": 0, "data": {"retCode": 0}}),
                },
            ],
        )
        .expect("playlist deletion result");
        assert_eq!(result.playlist_refs, playlist_refs);
        assert_eq!(result.extensions["all_deleted"], false);
        assert_eq!(result.extensions["results"][0]["directory_id"], 301);
        assert_eq!(result.extensions["results"][0]["deleted"], true);
        assert_eq!(result.extensions["results"][1]["directory_id"], 302);
        assert_eq!(result.extensions["results"][1]["returned_directory_id"], 0);
        assert_eq!(result.extensions["results"][1]["deleted"], false);
    }

    #[test]
    fn playlist_deletion_rejects_ambiguous_inputs_and_conflicting_results() {
        for playlist_refs in [
            Vec::new(),
            vec![ResourceRef::new(Platform::Qq, "7001").expect("playlist reference")],
            vec![ResourceRef::new(Platform::Qq, "dir:0").expect("zero directory reference")],
            vec![
                ResourceRef::new(Platform::Netease, "301")
                    .expect("cross-platform playlist reference"),
            ],
            (1..=101)
                .map(|id| {
                    ResourceRef::new(Platform::Qq, format!("dir:{id}"))
                        .expect("directory reference")
                })
                .collect(),
        ] {
            let error = match qq_playlist_delete_requests(&playlist_refs) {
                Ok(_) => panic!("invalid playlist deletion"),
                Err(error) => error,
            };
            assert_eq!(error.code, ErrorCode::InvalidRequest);
        }

        let target = || {
            qq_playlist_delete_requests(&[
                ResourceRef::new(Platform::Qq, "dir:301").expect("directory reference")
            ])
            .expect("playlist deletion request")
        };
        assert_eq!(
            map_qq_playlist_deletions(target(), Vec::new())
                .expect_err("missing deletion response")
                .code,
            ErrorCode::UpstreamError
        );
        for data in [
            json!({"retCode": 9, "result": {"tid": 0, "dirId": 0, "dirName": ""}}),
            json!({"retCode": 0}),
            json!({
                "retCode": 0,
                "result": {"tid": 7001, "dirId": 999, "dirName": "通勤"}
            }),
        ] {
            assert_eq!(
                map_qq_playlist_deletions(
                    target(),
                    vec![QqApiResponse {
                        data,
                        raw: json!({"code": 0})
                    }]
                )
                .expect_err("invalid deletion response")
                .code,
                ErrorCode::UpstreamError
            );
        }
    }

    #[test]
    fn playlist_detail_and_tracks_share_strict_metadata_and_pagination_mapping() {
        let raw = json!({
            "code": 0,
            "subcode": 0,
            "msg": "",
            "dirinfo": {
                "tid": 12345,
                "dirId": 101,
                "title": "通勤",
                "picurl": "https://example.test/playlist.jpg",
                "desc": "上下班",
                "songnum": 2,
                "listennum": 456,
                "creator": {
                    "musicid": 123456,
                    "nick": "Lotus",
                    "headurl": "https://example.test/avatar.jpg",
                    "encrypt_uin": "creator-encrypted"
                },
                "tags": ["流行", {"name": "通勤"}],
                "isfav": 1,
                "createTime": 1700000000,
                "updateTime": 1700000100
            },
            "songlist_size": 1,
            "songlist": [sample_track(97_773, "0039MnYb0qxYhV", "晴天")],
            "total_song_num": 2,
            "hasmore": 1
        });
        let locator = parse_qq_playlist_locator("12345").expect("locator");
        let detail = parse_qq_playlist_detail(raw.clone()).expect("detail response");
        validate_qq_playlist_detail_page(&detail, 0, 1).expect("detail pagination");
        let playlist = map_qq_playlist(locator, detail.clone(), raw.clone()).expect("playlist");
        assert_eq!(playlist.resource_ref.to_string(), "qq:12345");
        assert_eq!(playlist.name, "通勤");
        assert_eq!(playlist.track_count, Some(2));
        assert_eq!(playlist.tags, vec!["流行", "通勤"]);
        assert_eq!(playlist.subscribed, Some(true));
        assert_eq!(
            playlist.creator.expect("creator").resource_ref,
            Some(qq_ref("123456", "creator").expect("creator ref"))
        );

        let tracks = map_qq_playlist_tracks(0, 1, detail, raw).expect("tracks");
        assert_eq!(tracks.items.len(), 1);
        assert_eq!(
            tracks.items[0].resource_ref.to_string(),
            "qq:0039MnYb0qxYhV"
        );
        assert_eq!(tracks.pagination.total, Some(2));
        assert_eq!(tracks.pagination.next_offset, Some(1));
        assert!(tracks.pagination.has_more);
    }

    #[test]
    fn confirmed_login_persists_one_exact_account_without_exposing_the_key() {
        let store = Arc::new(RecordingCredentialStore::default());
        let provider = QqProvider::new(QqConfig {
            credential_store: Some(store.clone()),
            ..QqConfig::default()
        })
        .expect("provider");
        let credential = serde_json::from_value::<QqCredential>(json!({
            "musicid": 123456,
            "str_musicid": "123456",
            "musickey": "Q_H_L_private",
            "loginType": 2
        }))
        .expect("credential")
        .normalize()
        .expect("normalized credential");
        let profile = provider
            .persist_qq_credential("green-vip", &credential)
            .expect("persist credential");
        assert_eq!(profile.account, "green-vip");
        assert_eq!(profile.user_id.as_deref(), Some("123456"));
        assert_eq!(profile.extensions["login_type"], 2);
        let stored = store
            .load_platform(Platform::Qq)
            .expect("stored credentials");
        assert_eq!(stored.len(), 1);
        assert_eq!(stored[0].account, "green-vip");
        assert_eq!(stored[0].kind, QQ_CREDENTIAL_KIND);
        assert!(stored[0].secret().contains("Q_H_L_private"));
        assert!(!format!("{:?}", stored[0]).contains("Q_H_L_private"));
        assert!(provider.capabilities().contains(&Capability::QrLogin));
        assert!(provider.capabilities().contains(&Capability::PhoneLogin));
        assert!(
            provider
                .capabilities()
                .contains(&Capability::SessionManagement)
        );
        assert!(
            provider
                .capabilities()
                .contains(&Capability::AccountPlaylists)
        );
        assert!(provider.capabilities().contains(&Capability::Favorites));
        assert!(provider.capabilities().contains(&Capability::PlaylistWrite));
        assert!(
            provider
                .capabilities()
                .contains(&Capability::PlaylistSubscriptionWrite)
        );
        assert!(
            provider
                .capabilities()
                .contains(&Capability::TrackSubscriptionWrite)
        );
    }

    #[test]
    fn qq_login_credential_modes_separate_client_and_server_ownership() {
        let credential = serde_json::from_value::<QqCredential>(json!({
            "musicid": 123456,
            "str_musicid": "123456",
            "musickey": "Q_H_L_private",
            "loginType": 2,
            "musickeyCreateTime": 100,
            "keyExpiresIn": 50
        }))
        .expect("credential")
        .normalize()
        .expect("normalized credential");

        let client_only = QqProvider::new(QqConfig::default()).expect("client-only provider");
        let result = client_only
            .finish_qq_authentication("default", &credential, CredentialMode::Client)
            .expect("client-owned result");
        let caller_credential = result.credential.expect("caller credential");
        assert_eq!(result.profile.account, "default");
        assert_eq!(caller_credential.platform, Platform::Qq);
        assert_eq!(caller_credential.kind, QQ_CREDENTIAL_KIND);
        assert_eq!(caller_credential.expires_at, Some(150));
        assert_eq!(
            serde_json::from_str::<QqCredential>(caller_credential.secret())
                .expect("returned QQ credential")
                .normalize()
                .expect("normalized returned credential"),
            credential
        );
        assert_eq!(
            client_only
                .finish_qq_authentication("named", &credential, CredentialMode::Client)
                .expect_err("client mode must reject aliases")
                .code,
            ErrorCode::InvalidRequest
        );

        let store = Arc::new(RecordingCredentialStore::default());
        let both = QqProvider::new(QqConfig {
            credential_store: Some(store.clone()),
            ..QqConfig::default()
        })
        .expect("both-mode provider");
        let result = both
            .finish_qq_authentication("green-vip", &credential, CredentialMode::Both)
            .expect("both-owned result");
        let caller_credential = result.credential.expect("caller credential");
        let stored = store
            .load_platform(Platform::Qq)
            .expect("stored credential");
        assert_eq!(stored.len(), 1);
        assert_eq!(stored[0].account, "green-vip");
        assert_eq!(stored[0].secret(), caller_credential.secret());
    }

