    #[tokio::test]
    #[ignore = "requires live QQ Music services"]
    async fn live_public_playlist_owner_exposes_created_and_favorite_directories() {
        let provider = QqProvider::new(QqConfig {
            device_path: std::env::var_os("TUNEWEAVE_QQ_LIVE_DEVICE").map(Into::into),
            ..QqConfig::default()
        })
        .expect("provider");
        let playlist = provider
            .playlist("7039749142", None)
            .await
            .expect("live playlist detail");
        let creator_uin = playlist
            .creator
            .as_ref()
            .and_then(|creator| creator.resource_ref.as_ref())
            .map(ResourceRef::id)
            .expect("public creator UIN");
        let encrypted_uin = playlist
            .extensions
            .get("creator_encrypted_uin")
            .and_then(Value::as_str)
            .filter(|value| !value.is_empty())
            .expect("public creator encrypted UIN");
        let request = tuneweave_core::PageRequest {
            limit: 2,
            offset: 0,
            account: None,
        };
        let created = provider
            .user_created_playlists(creator_uin, &request)
            .await
            .expect("live user created playlists");
        assert!(created.pagination.total.is_some());
        assert!(created.items.iter().all(|item| !item.name.is_empty()));

        let favorite = provider
            .user_favorite_playlists(encrypted_uin, &request)
            .await
            .expect("live user favorite playlists");
        assert!(favorite.pagination.total.is_some());
        assert!(favorite.items.iter().all(|item| !item.name.is_empty()));

        let albums = provider
            .user_favorite_albums(encrypted_uin, &request)
            .await
            .expect("live user favorite albums");
        assert!(albums.pagination.total.is_some());
        assert!(albums.items.iter().all(|album| {
            album.platform == Platform::Qq
                && !album.id.is_empty()
                && !album.name.is_empty()
                && album.cover_url.is_some()
                && album.extensions["subscribed"] == true
        }));
        assert_eq!(albums.pagination.extensions["library_scope"], "user");
        assert_eq!(albums.pagination.extensions["response"]["code"], 0);

        let source = provider
            .playlist_source(encrypted_uin, "favorite_tracks", None)
            .await
            .expect("live favorite track source");
        assert_eq!(source.resource_ref.id(), encrypted_uin);
        assert_eq!(source.extensions["source_type"], "favorite_tracks");
        let source_items = provider
            .playlist_source_items(encrypted_uin, "favorite_tracks", &request)
            .await
            .expect("live favorite track source items");
        assert_eq!(
            source.track_count, source_items.pagination.total,
            "source metadata and item paging must report the same total"
        );
        assert!(
            source_items
                .items
                .iter()
                .all(|item| matches!(item, PlaylistPlayableItem::Track(_)))
        );
    }

    #[tokio::test]
    #[ignore = "requires live QQ Music services"]
    async fn live_nonempty_public_favorite_tracks_support_full_import_pages() {
        let provider = QqProvider::new(QqConfig {
            device_path: std::env::var_os("TUNEWEAVE_QQ_LIVE_DEVICE").map(Into::into),
            ..QqConfig::default()
        })
        .expect("provider");
        let users = provider
            .search_catalog(&search_query(SearchKind::User, 10, 0))
            .await
            .expect("live user search");
        let mut selected = None;
        for item in users.items {
            let SearchItem::User(user) = item else {
                continue;
            };
            let reference = user.resource_ref;
            let request = tuneweave_core::PageRequest {
                limit: 1,
                offset: 0,
                account: None,
            };
            let Ok(page) = provider
                .user_favorite_tracks(reference.id(), &request)
                .await
            else {
                continue;
            };
            if page
                .pagination
                .total
                .is_some_and(|total| (1..=500).contains(&total))
            {
                selected = Some(reference.id().to_owned());
                break;
            }
        }
        let selected = selected.expect("a public user with a bounded nonempty favorite list");
        let request = tuneweave_core::PageRequest {
            limit: 100,
            offset: 0,
            account: None,
        };
        let page = provider
            .playlist_source_items(&selected, "favorite_tracks", &request)
            .await
            .expect("full-size live favorite track page");
        assert!(!page.items.is_empty());
        assert!(page.pagination.total.is_some_and(|total| total > 0));
    }

    #[tokio::test]
    #[ignore = "requires live QQ Music services"]
    async fn live_batch_track_query_accepts_numeric_ids_and_mids() {
        let provider = QqProvider::new(QqConfig {
            device_path: std::env::var_os("TUNEWEAVE_QQ_LIVE_DEVICE").map(Into::into),
            ..QqConfig::default()
        })
        .expect("provider");
        let numeric = provider
            .tracks(&["100".to_owned(), "100".to_owned()], None)
            .await
            .expect("numeric batch");
        assert_eq!(numeric.len(), 2);
        assert_eq!(numeric[0].resource_ref, numeric[1].resource_ref);
        assert_eq!(numeric[0].extensions["numeric_id"], "100");

        let mids = provider
            .tracks(&["003w2xz20QlUZt".to_owned()], None)
            .await
            .expect("MID batch");
        assert_eq!(mids.len(), 1);
        assert_eq!(mids[0].resource_ref.to_string(), "qq:003w2xz20QlUZt");
        assert!(mids[0].extensions["media_mid"].as_str().is_some());
        assert!(mids[0].extensions.contains_key("song_type"));
        let write_identity =
            qq_playlist_write_track(&mids[0]).expect("live playlist write identity");
        assert!(write_identity.song_id > 0);
        assert!(write_identity.song_type >= 0);

        let typed = provider
            .tracks_with_options(&TrackDetailBatchRequest {
                items: vec![
                    TrackDetailRequestItem {
                        track_ref: qq_ref("003w2xz20QlUZt", "track").expect("MID ref"),
                        identifier_kind: TrackIdentifierKind::Mid,
                        song_type: Some(1),
                    },
                    TrackDetailRequestItem {
                        track_ref: qq_ref("2314161", "track").expect("special numeric ref"),
                        identifier_kind: TrackIdentifierKind::NumericId,
                        song_type: Some(113),
                    },
                    TrackDetailRequestItem {
                        track_ref: qq_ref("107479170", "track").expect("normal numeric ref"),
                        identifier_kind: TrackIdentifierKind::NumericId,
                        song_type: Some(1),
                    },
                    TrackDetailRequestItem {
                        track_ref: qq_ref("003w2xz20QlUZt", "track").expect("duplicate MID ref"),
                        identifier_kind: TrackIdentifierKind::Mid,
                        song_type: Some(7),
                    },
                ],
                account: None,
            })
            .await
            .expect("typed mixed batch");
        assert_eq!(typed.len(), 4);
        assert_eq!(typed[0].resource_ref.to_string(), "qq:003w2xz20QlUZt");
        assert_eq!(typed[1].resource_ref.to_string(), "qq:003Hx1mg4SlZVM");
        assert_eq!(typed[2].resource_ref.to_string(), "qq:0017ahqa0NvuNU");
        assert_eq!(typed[3].resource_ref, typed[0].resource_ref);
        assert_eq!(typed[0].extensions["requested_song_type"], 1);
        assert_eq!(typed[1].extensions["requested_song_type"], 113);
        assert_eq!(typed[3].extensions["requested_song_type"], 7);
    }

